(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["so"] = {"ui":{"skip":"U gudub nuxurka","back":"← Ku laabo AI-gile","lang.button":"Luuqad: {name}","lang.dialog":"Dooro luqad","lang.search":"Raadi luqadaha","lang.none":"Luqad waafaqsan ma jirto","lang.notYet":"{name} wali lama turjumin","theme.aria":"Beddel mawduuca: iftiin, mugdi ama madow","theme.toLight":"U beddel mawduuca iftiinka","theme.toDark":"U beddel mawduuca mugdiga","theme.toBlack":"U beddel mawduuca madow (madow dhab ah, ku fiican shaashadaha OLED)","words.underline":"Hoosta ka xarriiq erayadan bogga ku jira","words.underlineHelp":"Dul mar ama taabo eray dhibcaysan si aad u aragto macnihiisa.","words.col.todo":"Kaararka hadda la doortay: kooxdu waxay ku bilaabi doontaa kuwan marka xigta.","words.col.doing":"AI ayaa hadda ka shaqaynaya kaarkan.","words.col.review":"AI mid ah ayaa shaqada dhammeeyay; mid kale ayaa hubiya intaanay kuu soo gaadhin.","words.col.verify":"Adiga ayaa laga sugayaa: tijaabi oo ii sheeg haddii ay shaqayso.","words.col.team":"Qoraalladaada ama jawaabahaaga, oo sugaya in kooxdu qaado.","words.col.done":"La dhammeeyay oo la aqbalay.","index.title":"AI-gile: kooxdaada AI ee horumarinta, hal looxa","index.description":"AI-gile waa looxa kanban ee kooxaha barnaamijinta AI. Way shaqeeyaan inta aad hurdo; adiga waxaa kuu yimaada hal xirmo gaaban oo wax aad go'aamiso, tijaabiso oo aqbasho.","hero.logoAlt":"Astaanta looxa AI-gile","hero.h1.html":"Kooxdaada AI ee horumarinta, hal&nbsp;looxa.","hero.alpha":"🐣 Pre-alpha xiran","hero.alphaTitle":"Waa hore oo aan dhammaystirnayn: mahadsanid tijaabintaada!","hero.lede":"Way dhisaan inta aad hurdo. Waxaad toosaysaa hal xirmo gaaban: dhowr su'aalood, dhowr wax oo la tijaabiyo, hal ama laba dheeman oo guduudan-buluug ah. Guji, aqbal, oo ku laabo qaxwahaaga.","dl.windows":"Abka Windows","dl.browser":"Ku fur biraawsarka","dl.messenger":"📱 Messenger taleefankaaga","dl.soon":"Dhowaan","dl.notify":"🔔 I sheeg marka la furo","dl.notifySmall":"Alpha ama beta","hero.secondary":"Agile, laakiin kooxdu waligeed uma baahna qaxwada kulanka gaaban. (Kulamada gaagaabyada ah way sameeyaan si kastaba.)","pitch.h2":"AI-gile ereyo intaad rabto ku jira","pitch.lede":"Dooro dherer, hal eray ilaa 144. Dherer kasta waa sharaxaad u gaar ah, loo qoray cabbirkaas. Jiid sabuurka ama isticmaal fallaadhaha.","pitch.rangeLabel":"Dhererka ereyada","pitch.dice":"🎲 nooc kale","pitch.words.one":"{n} eray","pitch.words.other":"{n} eray","pitch.letters.one":"{n} xarfo","pitch.letters.other":"{n} xarfood","pitch.chars.one":"{n} xaraf","pitch.chars.other":"{n} xaraf","count.line.html.one":"{n} kaar ayaa hadda looxa ku jira","count.line.html.other":"{n} kaar ayaa hadda looxa ku jira","people.humans.html.one":"👥 {n} qof","people.humans.html.other":"👥 {n} qof","people.agents.html.one":"🤖 {n} wakiil","people.agents.html.other":"🤖 {n} wakiil","people.working.html.one":"⚡ {n} ayaa hadda shaqaynaya","people.working.html.other":"⚡ {n} ayaa hadda shaqaynaya","pre.title":"AI-gile: wax baa la dhisayaa","pre.description":"Halkan wax baa laga dhisayaa: loox ay kooxo AI ah ku dhisaan waxaad codsato, oo ay wax kugu baraan inta ay shaqeynayaan. Hadda waa pre-alpha xiran oo saaxiibo la wadaago.","pre.h1":"Halkan wax baa laga dhisayaa. 🤫","pre.line":"Loox ay kooxo AI ah ku dhisaan waxaad codsato, oo ay wax kugu baraan inta ay shaqeynayaan. Hadda waa pre-alpha xiran oo saaxiibo la wadaago.","pre.btn":"🔔 I sheeg marka la furo","pre.peek":"Muraayadda gadaasheeda: looxa dhabta ah, toos. Kaar kastaa waa xariiq midab leh.","pre.peekFake":"Muraayadda gadaasheeda: sidaan buu u eg yahay loox shaqeynaya.","pre.night":"🌙 Waardiyaha habeenka ayaa mas'uul ah · 😴 aadanuhu wuu nasanayaa","features.aria":"Wuxuu sameeyo","f.pile.h":"Hal xirmo adiga kuu ah","f.pile.html":"<b>Adiga</b> wuxuu ururiyaa wax kasta oo ku sugaya, mashruuc kasta: su'aalo, wax la tijaabiyo, hawlo uu qof kaliya samayn karo. Safkaaga ayaa kuu sheegaya waxa xiga iyo inta uu qaadanayo.","f.sleep.h":"Kooxo shaqeeya inta aad hurdo","f.sleep.p":"Mashruuc kastaa wuxuu leeyahay hoggaamiye iyo koox wakiilo AI ah. Kaarka ka dhiib faallo, kooxdu way toostaa, shaqada way qabataa, oo waxay kuu soo celisaa tallaabooyin uu qof daallan raaci karo.","f.tester.h":"Tijaabiyaha AI ayaa marka hore hubiya","f.tester.p":"Intaan wax adiga kuu imaan, tijaabiyuhu wuxuu raacaa tallaabooyinka nuqul ka mid ah abka wuxuuna muujiyaa waxa uu arkay, isagoo leh sawir shaashad. Dhex mar kuwa gudbay oo ku aqbal hal gujin.","f.proof.h":"Caddayn, ma ahan ballanqaadyo","f.proof.p":"Gacan-ka-gacan kasta wuxuu muujiyaa waxa isbeddelay: faylasha, farqiga, sawirada shaashadda. Uma baahnid inaad fureyso abka kasta si aad u aragto in la dhammeeyay.","f.chat.h":"La sheekayso hoggaamiyayaashaada","f.chat.p":"Tiir u eg Discord: hal astaan mashruuc kasta, dheeman guduudan-buluug ah waxa adiga ku baahan. Hoggaamiye u dir fikrad; wuxuu u beddelaa kaararka iyo qorshe, iyo badhanka ✅ Bilow.","f.tidy.h":"Is nadiifiya","f.tidy.p":"Kaararka isku xiga way is-dhex galaan, cinwaannada qalafsan waa la saxaa, hubinta tokenka ayaa koodhka ilaaliya mid khafiif ah. Wax yar oo la beddelo, wax yar oo la fekero.","f.private.h":"Adigaa leh, kombiyuutarkaaga","f.private.li1":"Looxu wuxuu ku shaqeeyaa mashiinkaaga, wuxuuna ka jawaabaa adiga oo keliya.","f.private.li2":"Fariimaha gaarka ah ee dadka dhexdooda waa la sir-qarsoodiyey dhammaadka ilaa dhammaadka.","f.private.li3":"Akoon ma jiro, raadraac ma jiro, cookies ma jiraan.","f.lang.h":"Luqaddaada","f.lang.p":"In ka badan 120 luqadood, Holandays, Welsh iyo Jabaaniis ilaa budhcad-badeed, Yoda iyo Klingon, oo leh beddelid degdeg ah oo Ingiriisi ah ee ereyada xirfadda.","f.service.h":"Fikrad ilaa adeeg dhab ah","f.service.p":"Ma ku dhistay AI wax dadku hadda isticmaalaan? U calaamadee adeeg, sabuuraduna waxay kaa caawinaysaa inaad si fiican u maamusho: hubinta shaqeynta, bog xaaladeed oo dadweyne, shilal leh dib-u-eegis qoran, isbeddello u baahan Go, kaydad maalin kasta la hubiyo. Caawimadu waxay ku bartaa tallaabo kasta intaad socoto.","msgr.h2":"AI-gile Messenger: kooxdaadu jeebkaaga","msgr.p1":"La hadal kooxdaada AI adigoon furin boardka. La sheekayso hoggaamiyeyaasha mashruucaaga iyo saaxiibbadaa, oo arag tallaabooyinka tijaabada ee kaar oo ka jawaab, dhammaan taleefankaaga.","msgr.p2":"Si aad isugu xirto, iskaan garee QR code ku yaal boardkaaga. Markii ugu horreysay? Sheeko demo ah oo saaxiibtinimo leh ayaa ku tusaysa.","msgr.when":"Marka hore Android, kadib nooc web ah oo loogu talagalay taleefannada iyo iPhone.","msgr.who":"Hoggaamiyaha mashruucaaga","msgr.b1":"Hagaajinta habka mugdiga diyaar weeye. Ma rabtaa tallaabooyinka tijaabada?","msgr.b2":"Haa, fadlan!","msgr.b3":"1. Fur Settings. 2. Dooro Dark. Si sax ah ma u muuqataa?","tl.aria":"Jadwalka laga bilaabo wada hadalkii ugu horreeyay ilaa qorshaha","tl.h2":"Sheekadii ugu horreysay ilaa waxa xiga","tl.lede":"Taariikho iyo waqtiyo dhab ah, aagga waqtigaaga. Maanta ka dib waa qorshe, taariikho lama ballanqaadin.","tl.today":"Maanta","tl.planned":"la qorsheeyay","tl.doing":"socda","tl.cards.one":"{n} kaar","tl.cards.other":"{n} kaar","join.h2":"Ku soo biir","join.lede":"AI-gile waxaa dhisaya nin gadh leh oo qariib ah, qaba AuDHD, oo dhowr jeer la dagaalamay caafimaadka maskaxda, iyo wakiilo badan oo samir badan. Hadda waa gaar, alpha xiran oo asxaab ah. Ma rabtaa inaad tijaabiso marka la furo?","join.btn":"Muuji xiisaha","join.small":"Iimayl ayaan kuu qori doonaa, wax kale ma jiro","footer.tag":"AI-gile. Raadraac la'aan, cookies la'aan, qaxwo kulan la'aan.","footer.licence":"Shahaadada ganacsiga","footer.status":"Xaaladda","footer.privacy":"Waxa aan haynno","footer.thanks":"Wicitaanada waxaa suurtagaliyay ChilledChat","form.sending":"Waa la dirayaa…","form.failed":"Ma shaqayn: mar dambe isku day.","form.offline":"AI-gile lama gaari karin: mar dambe isku day.","form.keep":"Waxaan u isticmaalnaa oo keliya inaan kuugu jawaabno, kadibna waan tirtirnaa. Raadraac la'aan, cookies la'aan.","form.keepLink":"Waxa aan haynno","interest.title":"AI-gile: i sheeg marka alpha la furo","interest.description":"Iimaylkaaga reeb si aad u ogaato marka alpha ama beta xiran ee AI-gile la furo.","interest.h1":"🔔 I sheeg marka la furo","interest.lede":"AI-gile waa pre-alpha xiran. Iimaylkaaga reeb, mar keliya ayaan kuu qori doonnaa marka meel adiga kuu jirto.","interest.email":"Iimaylkaaga","interest.which":"Tijaabo kee?","interest.alpha":"Alpha xiran: hore, qallafsan, isbeddello badan","interest.beta":"Beta: xasiloon, dambe","interest.both":"Mid kasta, kii hore yimaada","interest.submit":"Liiska igu dar","interest.thanks":"Mahadsanid! Liiska waad ku jirtaa.","licence.title":"AI-gile: shahaadada ganacsiga","licence.description":"Ma ku isticmaashaa AI-gile ganacsigaaga? Codso shahaado ganacsi oo bilaash ah.","licence.h1":"📜 Shahaadada ganacsiga","licence.lede":"Ma ku isticmaashaa AI-gile shaqada? Noo sheeg yaad tahay iyo waxaad qabato. Haddii wax wanaagsan sameeyo, shahaadadu waa bilaash.","licence.company":"Shirkadda","licence.website":"Boggaga","licence.what":"Waxaad qabato","licence.how":"Sida ay adduunka ugu caawiso","licence.email":"Iimaylka","licence.submit":"Codso","licence.thanks":"Mahadsanid! Iimayl ayaan kaaga jawaabi doonnaa.","status.title":"Xaaladda AI-gile","status.h1":"Xaaladda AI-gile","status.quiet":"Wax walba way degan yihiin","status.intro":"AI-gile ma shaqaynayaa hadda? Boggan wuxuu 5-tii daqiiqoba mar hubiyaa website-ka, wadaagista looxyada, wicitaannada iyo soo dejinta.","status.up":"Wuu shaqaynayaa (wuxuu ku jawaabay {ms} ms)","status.slow":"Kama jawaabin hubintii u dambaysay, mar kale ayaan isku dayayaa","status.down":"Wuu xiran yahay: kama jawaabin labadii hubin ee u dambeeyay","status.svc.web":"Website-ka","status.svc.web.offers":"Boggan: waxa uu AI-gile yahay, iyo foomka xiisaha","status.svc.boards":"Wadaagista looxyada","status.svc.boards.offers":"Looxyo dadweyne, fariimo saaxiibbada dhexdooda ah iyo casuumado","status.svc.calls":"Wicitaannada","status.svc.calls.offers":"Cod, muuqaal iyo wadaagista shaashadda gudaha AI-gile","status.svc.download":"Soo dejinta","status.svc.download.offers":"Rakibaha Windows iyo xiriirinnada casuumadda","status.checking":"Waa la hubinayaa…","status.offline":"Adeegga xaaladda hadda lama gaari karo (mar kale ayaan isku dayayaa)","status.updated":"la cusboonaysiiyay {ago}","status.justNow":"hadda dhawaan","status.min":"{n} daqiiqo ka hor","status.hours":"{n} saac ka hor","status.days":"{n} maalmood ka hor","privacy.title":"AI-gile: waxa aan haynno","privacy.h1":"Waxa aan haynno","privacy.lede":"Si kooban: kaliya waxaad noo soo dirto, mana aha muddo dheer.","privacy.only":"Kaliya waxaad noo soo dirto: waxaad ku qorto foom, sida iimaylkaaga. Wax kale oo adiga kugu saabsan ma jiraan.","privacy.sealed":"Waa la shaabadeeyaa si server-kayagu aanu u akhrin karin: biraawsarkaaga gudahiisa ka hor intaanu bixin (biraawsar duug ah, isla marka uu yimaado). Kaliya looxayaga ayaa furi kara.","privacy.server":"Server-ka waa laga tirtiraa isla marka uu gaaro looxayaga. Wax kasta oo halkaas ku haray 30 maalmood kadib si kastaba waa la tirtiraa.","privacy.board":"Waxaan ku haynaa looxayaga oo keliya ilaa aan kaaga jawaabno, kadibna halkaasna waan ka tirtirnaa.","privacy.none":"Raadraac la'aan, cookies la'aan, falanqayn la'aan.","privacy.local":"Luqaddaada iyo doorashadaada iftiinka ama mugdiga waxay ku jiraan biraawsarkaaga. Weligood nalooma soo diro.","privacy.ask":"Ma rabtaa in hore loo tirtiro? Ka jawaab iimaylkayaga oo noo sheeg.","live.h2":"Daawo markii la dhisayo, tooska","live.caption":"Kaarkasta waa qarsoon yahay: waxaad aragtaa qaabka shaqada, ma aha erayada.","live.watching.one":"tooska: {n} ayaa daawanaya","live.watching.other":"tooska: {n} ayaa daawanaya","live.last.now":"Kaarkii ugu dambeeyay waa la dhaqaajiyay hadda","live.last.min.one":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} daqiiqo ka hor","live.last.min.other":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} daqiiqo ka hor","live.last.hour.one":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} saac ka hor","live.last.hour.other":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} saacadood ka hor","live.last.day.one":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} maalin ka hor","live.last.day.other":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} maalmood ka hor","live.offline":"Looxa tooska ah wuxuu qaadanayaa nasasho yar. Dhawaan dib u soo eeg.","live.cols":"Backlog|Waxa la sameeyo|Socda|Kooxdu way eegaysaa|Adiga oo test samaynaya|Kooxda|La dhammeeyay","footer.models":"AI-gile waxay kuu socodsiisaa moodooyinka AI. Waxay yiraahdaan iyo waxay sameeyaan iyagaa leh, haddaba hubi ka hor intaanad aamini.","privacy.ai.h":"Qaybta AI","privacy.ai.models":"AI-gile waa boardka. Shaqada waxaa qaata moodooyinka AI ee shirkado kale, sida Claude, Codex iyo Gemini, akoonnadaada.","privacy.ai.check":"Waxay qoraan iyo waxay sameeyaan iyagay ka yimaadaan, waxayna noqon karaan khalad. Hubi ka hor intaadan ku tiirsanaan ama dayn.","privacy.ai.files":"Waxay bedelaan faylasha, waxayna ordaan amarro gudaha faylalka aad ku xirto. Kaydi nuqul kaydsan.","privacy.ai.send":"Waxaad siiso moodel waxay aadaa shirkadda socodsiisa, iyadoo hoos imanaysa shuruudahooda. Shuruudaha iyo kharashka shirkad kasta ayaa khuseeya.","privacy.ai.asis":"AI-gile waa nooc tijaabo hore ah, sida uu yahay ayaa la siinayaa."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotyo.","Wakiilnimo."]},{"n":2,"texts":["Kanban robot.","Wakiilo nidaamsan.","Fikrado dhisan."]},{"n":3,"texts":["Kanban u ah robotyada.","Fikrad, dhis, aqbal.","Kanban wakiilo bilaash."]},{"n":5,"texts":["Looxa kanban oo wakiilo maamulaan.","Adigu qor kaararka. Wakiilladu dhis.","Bilaash, gudaha, tijaabo, qosol yar."]},{"n":8,"texts":["Looxa kanban oo bilaash ah halka wakiilo AI shaqeeyaan.","Qor fikrad. Wakiilladu way dhisaan. Adigu aqbal.","Agile hal qof iyo robotyo badan oo samir badan."]},{"n":13,"texts":["Looxa kanban ee kombiyuutarkaaga ku jira halka wakiilo AI ay kaararka qaataan oo ay ku shaqeeyaan.","Qor fikrad. Koox wakiilo ah ayaa dhisa. Tijaabiye ayaa hubiya. Adigu waxaad dhahdaa haa.","Bilaash, akoon la'aan, raadraac la'aan: looxa, robotyo yar, iyo adiga oo xukumaya."]},{"n":21,"texts":["AI-gile waa looxa kanban oo lagu la shaqeeyo wakiilo AI ah oo barnaamijiya. Iyagu kaararka way qaataan; adiguna waad tijaabisaa oo aqbashaa.","Mashruuc kastaa wuxuu helaa hoggaamiye iyo koox wakiilo AI ah. Kaar kasta faallo ka qor, kooxduna way shaqo bilaabaysaa.","Looxa hawlaha shaqsiyeed oo bilaash ah oo kombiyuutarkaaga ku shaqeeya. Shaqaaluhu waa robotyo. Kan dhihi kara haa waa adiga."]},{"n":34,"texts":["Fikradaha looxa ayaad saartaa. Koox wakiilo AI ah ayaa u beddesha qaybo shaqeeya, way tijaabisaa, waxayna kuu soo celisaa tallaabooyin lagu tijaabiyo. Wax lama yiraahdo waa dhammaaday ilaa aad dhahdo.","AI-gile waa looxa kanban oo guri lagu sameeyay, kaas oo Rich ku dhisay caawimo badan oo ka timid wakiilada uu hadda xukumo. Waa bilaash, kombiyuutarkaaga ayuu ku shaqeeyaa, waxaana lala wadaagaa asxaabta, lama iibiyo.","Ka fikir looxa kanban oo caadi ah, oo leh tiirar laga bilaabo Backlog ilaa La dhammeeyay, marka laga reebo in kaararka qaataan wakiilo AI. Waxay sheegaan horumarka, waxay weydiiyaan marka ay hakadaan, had iyo jeer waxayna sugaan oggolaanshahaaga."]},{"n":55,"texts":["AI-gile waa looxa kanban oo kooxdu ka kooban tahay wakiilo AI. Mashruuc kastaa wuxuu leeyahay hoggaamiye qorsheeya shaqada iyo caawiyayaal dhisa. Marka sifo diyaar tahay, tijaabiye AI ah ayaa tijaabiya oo sawir shaashad qaata, ka dibna waxay ku dhacdaa xirmadaada. Aqbal, ama faallo qor, waana dib u sameeyaan.","Wuxuu ku bilaabmay hab qof keliya uu ku raaco fadhiyo badan oo barnaamijin AI ah isku mar, wuuna kobcay oo noqday looxa dhab ah. Wuxuu ku shaqeeyaa mashiinkaaga, akoon uma baahna, raadraac ma laha. Waa bilaash asxaabta iyo kuwa xiisaynaya. Sidoo kale ma dhammaystirna, sidaa darteed filo geesyo qallafsan iyo layaab mararka qaarkood.","Halkan waa nooca daacadda ah. Adigu weli waa inaad fikrado yeelataa, weliba waa inaad hubisaa natiijooyinka. AI-gile wuxuu qabtaa wax kasta oo u dhexeeya: kaararka ayuu u dhigaa nidaam, wuxuu kiciyaa wakiilka saxda ah marka aad faallo qorto, wuxuu tusaa si sax ah waxa isbeddelay, wuxuuna dhammaantood ku soo ururiyaa hal xirmo gaaban adiga kuu ah."]},{"n":89,"texts":["AI-gile waa looxa kanban oo bilaash ah oo aad ku wadato kombiyuutarkaaga. Halkii dad, mashruuc kastaa wuxuu leeyahay koox wakiilo AI ah: hoggaamiye u beddela fikradahaaga kaararka iyo qorshe, iyo caawiyayaal kaararka qaata marka la horumariyo. Marka wax la dhiso, tijaabiye AI ah ayaa raaca tallaabooyinka tijaabada oo kuu muujiya waxa uu arkay. Kadib wuxuu ku sugaa hal xirmo la yiraahdo Adiga. Waad aqbashaa, ama faallo ayaad qortaa kooxduna mar kale ayay isku dayaan. Wax kuma gaaraan La dhammeeyay adiga la'aantaa.","Dhowr wax oo laga yaabo inaadan filayn. Ilaaliyaha habeenka ayaa buuxiya tiirka Waxa la sameeyo inta aad hurdo, isagoo dooranaya kaararka aan jawaab kaa rabin. Tiriyaha tokenka ayaa muujiya intii wakiilladu isticmaaleen maanta iyo toddobaadkan, Habka Tokenka La'aan ayaana u sheegaya inay joojiyaan isticmaalka. Waad la fariisan kartaa asxaabta, fariimaha gaarka ahna waa la sir-qarsoodiyey dhammaadka ilaa dhammaadka. Looxu wuxuu ku hadlaa ilaa 120 luqadood, oo ay ku jiraan Holandays, Flemish, budhcad-badeed iyo Klingon. Midkoodna sentimo ma ku kacayo, cidna isku dayin inay kuu iibiso.","AI-gile waa mashruuc yar oo shakhsi ah, ma aha shirkad. Rich wuxuu rabay inuu ilaaliyo dhowr mashruuc oo barnaamijin AI ah isagoo aan furin abka kasta si uu u hubiyo, sidaa darteed isaga iyo wakiilladu waxay dhiseen looxa, kadibna looxa ayay ku dhiseen inta kale ee naftiisa. Waa pre-alpha xiran, taasoo la macno ah inuu shaqeeyo, inta badan, koox yar oo asxaab ah. Bog qiimo ma leh, wargeys ma leh, qorshe kobac ma leh. Haddii ay kuu ekaato mid faa'iido leh, waad codsan kartaa inaad tijaabiso marka wax yar ka badan la furo."]},{"n":144,"texts":["AI-gile waa looxa kanban oo hal qof iyo wakiilo AI badan u ah. Wuxuu ku shaqeeyaa kombiyuutarkaaga wuxuuna yahay bilaash dhan. Waxaad ku darsataa mashruucyo, mid kastana wuxuu helaa hoggaamiye iyo koox yar. Waad la sheekaysataa hoggaamiyaha, in yar sida Discord, waxaadna sifaysaa fikrad; hoggaamiyuhu wuxuu u beddelaa kaararka iyo qorshe, kadibna wuu sugaa inta aad gujinayso Bilow. Kooxdu waxay kaararka u gudubtaa sida mudnaanta u ahaato, iyadoo isticmaalaysa xariiq amar fudud oo loo sameeyay moodooyinka luqadda. Intaan wax kuu soo noqon, tijaabiye AI ah ayaa raaca tallaabooyinka nuqul ka mid ah abka oo ku lifaaqa sawir shaashad. Shaqada dhammaatay waxay ku dhacdaa xirmadaada iyada oo leh faylasha la beddelay iyo farqiga. Waad aqbashaa, ama faallo ayaad ka tagtaa kooxduna way toostaa oo mar kale isku daydaa. Kaar u gudbin La dhammeeyay waxaad samayn kartaa adiga oo keliya.","Maalin AI-gile la qabo, qiyaas ahaan. Fiidkii waxaad ka tagtaa dhowr faallo: badhankan meel qaldan buu yahay, liiskaas waa in la kala saaro, ma yeelan karnaa habka mugdiga. Waad seexataa. Wakiilladu faallooyinka way akhriyaan, isbeddellada way samaystaan, way tijaabiyaan oo way kuu soo celiyaan. Haddii Waxa la sameeyo engegto, ilaaliyaha habeenka ayaa ka buuxiya backlog-ga kaararka aan jawaab kaa rabin. Subaxdii waxaa jirta hal xirmo gaaban: dhowr su'aalood iyo dhowr wax la tijaabiyo, mid kastana wuxuu leeyahay tallaabooyin uu qof hurdo ku jiro raaci karo iyo sawir muujinaya inuu shaqeeyo. Waad dhex marisaa, waxa wanaagsan aqbashaa, inta kalena celisaa. Tiriyaha tokenka ayaa muujiya waxa dhammaantood isticmaaleen, Habka Tokenka La'aan-na wuxuu u diyaar yahay toddobaadyada dhaqaalaha yar. Kadib waxaad cunta quraac, taas oo wakiilladu weli kaa caawin kari waayeen.","Marka hore, waxa AI-gile ahayn maaha. Ma aha startup, lama iibiyo, cidna ma ururiso xogtaada. Waa looxa bilaash ah oo kombiyuutarkaaga ku shaqeeya, akoon la'aan, raadraac la'aan iyo cookies la'aan. Waxa uu yahay: hal meel nadiif ah oo aad ku aragto mashruucyada barnaamijinta AI dhammaan isku mar, iyadoo koox wakiilo ah ay samaynayaan kaararka adiguna aad go'aamineyso. Wuxuu isku dhex yeelaa kaararka isku xiga, wuxuu saxaa cinwaannada qalafsan, wuxuuna fiiriyaa in koodhku khafiif ahaado. Wuxuu ku hadlaa ilaa 120 luqadood, laga bilaabo Holandays iyo Flemish ilaa budhcad-badeed iyo Klingon. Asxaabtu waa isu qori karaan gaar ahaan oo sir-qarsoodi ah. Waxaa dhisay Rich iyo tiro badan oo wakiilo samir badan ah, inta badan isagoo isticmaalaya naftiisa. Waa pre-alpha xiran, sidaa darteed meelaha qaarkood waa qallafsan yahay. Haddii ay kuu ekaato wax xiiso leh, si wanaagsan weydiiso, laga yaabee inaad hore u gasho."]}],"quips":{"1":"Hal eray. Dhiirrasho. Laga yaabee xad-dhaaf.","3":"Seddex eray. Hadda ka daacad badan bogagga badeecadaha intooda badan.","8":"Siddeed eray. Wali way ka gaaban yihiin kulan gaaban.","21":"Dhererradu waa story points, dariiqa. Hubaal ayay yihiin.","55":"Shan iyo konton eray. Laba kaar ayaa la dhammeeyay intaad akhrinaysay.","144":"Tani waa tan dheer. 233 ma jirto. Wakiilladii way seexdeen."}},"timeline":{"first-idea.name":"Fikraddii ugu horreysay","first-idea.line":"Wada hadalkii ugu horreeyay, intaan koodh jirin.","first-board.name":"Looxii ugu horreeyay","first-board.line":"Loox raacaya dhismihiisa: kaararka, tiirarka, jiid oo dhig, mashruucyada.","team-roles.name":"Koox iyo doorar","team-roles.line":"Astaamaha wakiilada, qaabdhismeedyada kooxaha, meelaha iyo yaa maxay qabanaya.","install.name":"Rakibid iyo daabacaado","install.line":"Zip uu saaxiib rakibi karo, is-cusboonaysiin, kanaalo iyo dib u noqosho.","usage-saver.name":"Badbaadiyaha isticmaalka","usage-saver.line":"Cabbir waxa socodku ku kacaan, koodhka khafiif ka dhig, xadkaaga badbaadi.","friends.name":"Asxaab iyo wadaagid","friends.line":"Fariimo gaar ah, gudbiye qarsoon, casuumaado, doorar iyo mashruucyo la wadaago.","languages.name":"Luqadaha","languages.line":"Qoraal shaashad kasta faylka luqadda, Holandays iyo Flemish marka hore.","ai-tester.name":"Tijaabiyaha AI","ai-tester.line":"Tijaabiye ayaa marka hore hubiya gacan-ka-gacan kasta oo muujiya waxa uu arkay.","website.name":"Mareegta","website.line":"aigile.lol, hordhaca iyo jadwalkan.","streaming.name":"Sheeko iyo tooska","streaming.line":"Discord, Twitch, OBS, habka tooska, GIF-yo iyo emoji.","no-ai.name":"Nooca aan AI lahayn","no-ai.line":"Loox dadka aan AI la'aan koodhka qorin, iyo looxyo dadweyne.","night-watch.name":"Ilaaliyaha habeenka","night-watch.line":"Ilaaliye iyo Scrum Master ayaa kooxaha shaqada ku haya inta aad hurdo.","p-more.name":"Wax kale oo dhan","p-more.line":"Fikrado yar oo wali sugaya inay noqdaan kuwa xiga.","p-android.name":"Taleefan iyo Android","p-android.line":"Looxaaga ka gaar taleefanka, kadibna abka Android ee asalka ah.","p-release.name":"Alpha iyo wixii ka dambeeya","p-release.line":"Alpha xiran, bogga tooska ah, kadibna beta.","p-languages.name":"Luqado dheeraad ah","p-languages.line":"130 luqadood, iyo hab quusta luqadda oo loogu talagalay kuwa baranaya.","p-engines.name":"Mishiinno AI dheeraad ah","p-engines.line":"Wakiil kasta u dooro Claude, Codex, Gemini, Copilot ama Cursor.","p-pro.name":"Hab-dhaqan xirfadeed","p-pro.line":"Calaamado khatar, albaabada isku-darka, kaararka dhacdooyinka iyo ilaalin.","p-self.name":"Ku daryeelidda adiga","p-self.line":"Habka daalka, xusuusinta is-daryeelka iyo 4:20.","p-servers.name":"Serfarro iyo ballaarin","p-servers.line":"Dejinta serfarka guud, doorar iyo qorsheynta kobaca.","p-livestream.name":"Dheeraadka tooska","p-livestream.line":"Sheekada Twitch, emoji gaar ah iyo muuqaal tooska ah oo dadweyne."},"words":{"button":"📖 Ereyada xirfadda","h":"📖 Ereyada la sharraxay","intro":"Tababar bilaash ah oo luuqad fudud ah: eray kasta oo aad la kulanto laga bilaabo fikrad hore ilaa adeeg dadku ku tiirsan yihiin, oo ay ku jiraan Agile, dhisid, ammaan ku haynta iyo ka shaqaynta AI jidka dhexdiisa.","search":"Raadi eray…","none":"Eray ku habboon ma jiro.","close":"Xir","count":{"one":"{count} eray","other":"{count} eray"},"groups":[{"id":"idea","name":"💡 Fikrad iyo sahan"},{"id":"plan","name":"🗺️ Qorshaynta shaqada"},{"id":"agile","name":"🔁 Habab shaqo oo agile ah"},{"id":"build","name":"🛠️ Dhisidda"},{"id":"test","name":"🧪 Tijaabo iyo tayo"},{"id":"change","name":"🔀 Beddelid ammaan ah"},{"id":"run","name":"🛎️ Maamulidda adeeg"},{"id":"sec","name":"🔒 Amni iyo qarsoodi"},{"id":"ai","name":"🤖 Ka shaqeynta AI"},{"id":"money","name":"💰 Lacag iyo shatiyo"}],"list":[{"id":"discovery","g":"idea","word":"Sahan (Discovery)","text":"Marxaladda hore ee la ogaado dhibaatada mudan in la xalliyo iyo cidda loogu talagalay, ka hor intaan wax la dhisin.","also":["marxaladda sahanka","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Qeexidda dhibaatada","text":"Hal ama laba jumladood oo sheegaya cidda dhibaatadu haysato, waxa ay tahay iyo sababta ay muhiim u tahay, si qof walba hal wax u beegsado.","also":["problem statement","problem statements"]},{"id":"user","g":"idea","word":"Isticmaale (User)","text":"Qof isticmaala waxa aad dhisto. Baahiyihiisa ayaa shaqada loo qabanayaa.","also":["isticmaalaha","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Daneeye (Stakeholder)","text":"Qof kasta oo danaynaya sida shaqadu u dhammaato ama ay saameyso, sida dadka bixinaya lacagta, isticmaalaya ama taageeraya.","also":["daneeyaasha","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Persona (qof tusaale ah)","text":"Qof male ah laakiin u eg mid dhab ah oo metelaya hal nooc oo isticmaale, si kooxdu u weydiin karto “Sam ma u fududaan doontaa tan?”","also":["persona","personas"]},{"id":"userresearch","g":"idea","word":"Cilmi-baadhis isticmaale","text":"La hadalka iyo daawashada dad dhab ah si loo ogaado waxa ay u baahan yihiin, halkii la qiyaasi lahaa.","also":["user research","user interviews","wareysiyada isticmaalayaasha"]},{"id":"journey","g":"idea","word":"Safarka isticmaalaha","text":"Tillaabooyinka uu qofku qaado si uu wax u dhammeeyo, laga bilaabo markii ugu horreysay ee uu maqlo ilaa uu dhammeeyo, xitaa meelaha ka baxsan alaabtaada. Sawiriddiisu waxay muujisaa halka uu ku xayiro.","also":["user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Meesha ku dhibta (Pain point)","text":"Wax maanta dadka cadhaysiiya ama gaabiya. Alaabaha wanaagsani way baabi'iyaan dhibaatooyinkan.","also":["pain point","pain points"]},{"id":"assumption","g":"idea","word":"Filasho (Assumption)","text":"Wax aad rumaysan tahay laakiin aanad weli hubin. Qorista filashooyinku waxay muujisaa waxa marka hore la tijaabiyo.","also":["assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Male-awaal (Hypothesis)","text":"Qiyaas ugu wanaagsan oo aad qorshaynayso inaad hubiso, oo leh waxa aad filayso inay dhacaan, sida “dadku way is-diiwaangelin doonaan haddii bisha ugu horreysa bilaash tahay”.","also":["hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Tijaabo (Experiment)","text":"Tijaabo yar oo la qorsheeyay si loo ogaado in fikraddu shaqayso, ka hor intaan wax badan la gelin.","also":["experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Caddaynta fikradda (PoC)","text":"Isku day degdeg ah oo aan dhammaystirnayn si loo arko in fikraddu xitaa shaqayn karto. Badanaa waa la tuuraa marka jawaabta la helo.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Qaab hore (Prototype)","text":"Nuqul hore oo alaabta ah, badanaa sawirro la riixi karo, si fikradda dadka looga tijaabiyo ka hor intaan si sax ah loo dhisin.","also":["prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe (sawir fudud)","text":"Sawir fudud oo shaashad ah oo muujinaya meesha waxyaabuhu galayaan, midab ama waxyaabo dhab ah la'aan.","also":["wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"Mockup (sawir faahfaahsan)","text":"Sawir faahfaahsan oo muujinaya sida shaashad u eegi doonto, oo leh midabyo iyo qoraal dhab ah, laakiin weli waxba ma shaqeeyaan.","also":["mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Sababaynta ganacsiga","text":"Sababaha mashruuc loo qabanayo: waxa uu ku kacayo, waxa uu keenayo ama badbaadinayo, iyo khataraha.","also":["business case","business cases"]},{"id":"feasibility","g":"idea","word":"Suurtagal (Feasibility)","text":"In wax runtii la dhisi karo oo la daryeeli karo iyadoo la isticmaalayo waqtiga, lacagta iyo xirfadaha aad haysato.","also":["feasibility"]},{"id":"outcome","g":"idea","word":"Natiijo (Outcome)","text":"Isbeddelka aad dadka ugu rabto, sida ballamo yar oo la seegay. Wuu ka muhiimsan yahay inta la dhiso.","also":["outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Wax soo saar (Output)","text":"Wax kooxdu samayso, sida shaashad cusub ama warbixin. Samayntiisu macnaheedu maaha inuu si toos ah qof u caawiyo.","also":["output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Cabbirka guusha (Success metric)","text":"Tiro kuu sheegaysa in shaqadu samaysay waxa loogu talagalay, sida dad badan oo dhammeeya dalabkooda.","also":["success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Tilmaamaha waxqabadka muhiimka ah (KPI)","text":"Tiro muhiim ah oo aad la socoto si aad u aragto in wax si fiican u socdaan, sida inta qof ee is-diiwaangeliya usbuuc kasta.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Hadafyada iyo natiijooyinka muhiimka ah (OKRs)","text":"Hab lagu dejiyo hadafyo: hadafku wuxuu sheegayaa waxa aad rabto, dhawr natiijo oo muhiim ah ayaana ah tirooyinka muujinaya inaad gaartay.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Alaab (Product)","text":"Waxa loo dhisayo oo loo daryeelayo isticmaalayaashiisa, sida app, website ama qalab.","also":["product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Aragtida alaabta","text":"Bayaan gaaban oo sheegaya cidda alaabtu caawinayso iyo halka ay u socoto mustaqbalka fog.","also":["product vision","vision statement"]},{"id":"po","g":"plan","word":"Mulkiilaha alaabta (Product owner, PO)","text":"Qofka go'aamiya waxa la dhisayo iyo kala horreyntooda, si kooxdu mar walba ugu shaqayso waxa ugu muhiimsan. AI-gile dhexdiisa, adiga ayaa ah.","also":["PO","product owner","product owners"]},{"id":"pm","g":"plan","word":"Maamulaha alaabta (Product manager, PM)","text":"Qofka daryeela jihada alaabta: dhibaatooyinka ay xalliso, cidda loogu talagalay iyo sababta. PM waxay sidoo kale macnaheedu noqon kartaa maamulaha mashruuca, ee hubi midka loola jeedo.","also":["PM","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"Maamulaha mashruuca (Project manager)","text":"Qofka hubiya in mashruucu ku dhammaado waqtigiisa iyo miisaaniyaddiisa, isagoo la socda cidda waxa qabanaysa iyo goorta.","also":["project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Khariidadda jidka (Roadmap)","text":"Qorshe guud oo ah waxa soo socda bilaha dambe, si isku xigta. Wuxuu muujiyaa jihada, ma aha taariikho sax ah, wuuna isbeddelaa marka aad wax baratid.","also":["roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Calaamad muhiim ah (Milestone)","text":"Qodob mashruuca ku jira oo mudan in la calaamadiyo, sida “nooca koowaad waa la daah-furay” ama “100 isticmaale”.","also":["milestone","milestones"]},{"id":"mvp","g":"plan","word":"Alaabta ugu yar ee waxtarka leh (MVP)","text":"Nooca ugu yar ee alaab oo weli dad dhab ah u faa'iido leh, si aad uga baratid goor hore.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Shuruud (Requirement)","text":"Wax alaabta dhammaaday ay tahay inay samayso ama ay noqoto.","also":["shuruudo","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Baaxadda shaqada (Scope)","text":"Waxa shaqada ku jira iyo, si le'eg muhiim, waxa ku jirin.","also":["scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Ballaarashada baaxadda (Scope creep)","text":"Marka wax badan oo dheeraad ah shaqada lagu daro si tartiib tartiib ah, iyadoo cidina aysan ku heshiin waqti ama kharash dheeraad ah, sidaas darteed aanay marna si buuxda u dhammaan.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Sifo (Feature)","text":"Hal shay oo alaabtu dadka u qaban karto, sida “dib u deji erayga sirta ah”.","also":["sifo","sifooyin","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Shaqo weyn (Epic)","text":"Qayb shaqo oo weyn, aan hal mar la dhammayn karin, sidaas darteed loo kala qaybiyo kaarar yaryar.","also":["epic","epics"]},{"id":"story","g":"plan","word":"Sheekada isticmaalaha (User story)","text":"Qayb yar oo shaqo ah oo laga qoray dhinaca isticmaalaha: “Anigoo ah macmiil, waxaan rabaa inaan kaydiyo dambiilkayga, si aan markii dambe u dhammeeyo.” Waxay bilaabaysaa wada-hadal ku saabsan waxa la dhisayo.","also":["user story","user stories"]},{"id":"ac","g":"plan","word":"Shuruudaha aqbalidda (AC)","text":"Hubinnada uu kaar ku gudbo si loogu tiriyo mid dhammaaday, oo la isku raacay ka hor inta aan shaqadu bilaabmin, sida “dambiilku wuu jiraa kadib markaan ka baxo oo dib u galo”.","also":["AC","acceptance criteria"]},{"id":"task","g":"plan","word":"Hawl (Task)","text":"Hal hawl oo la qabanayo, badanaa tillaabo yar oo ka mid ah sheeko weyn.","also":["task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Tigidh (Ticket)","text":"Erey kale oo kaarka loo yaqaan: hal qayb shaqo ama hal codsi, oo laga daba socdo bilowga ilaa dhammaadka.","also":["ticket","tickets"]},{"id":"priority","g":"plan","word":"Mudnaan (Priority)","text":"Intee leeg bay muhiim ama degdeg u tahay marka lala barbardhigo wax walba, si shaqada ugu muhiimsan marka hore loo qabto.","also":["mudnaanta","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Mudnaan-siin (Prioritisation)","text":"Ku kala horraysiinta shaqada sida ay muhiimaddeedu tahay. Hab caadi ah waa MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Qiyaas (Estimate)","text":"Qiyaas ugu fiican oo ku saabsan inta ay le'eg tahay ama inta ay qaadanayso qayb shaqo ah. Waa qiyaas, ma aha ballan.","also":["estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Dhibcaha sheekada (Story points)","text":"Hab lagu qiyaaso cabbirka shaqada iyadoo kaararka la isbarbar dhigayo (“qiyaastii laba jeer ka weyn kaas”) halkii saacado lagu qiyaasi lahaa. Looma talagalin in kooxaha lagu isbarbar dhigo.","also":["story point","story points"]},{"id":"tshirt","g":"plan","word":"Cabbirka funaanadda (T-shirt sizing)","text":"Qiyaasidda cabbirka shaqada sida S, M, L ama XL. Degdeg ah oo ku filan qorshaynta hore.","also":["t-shirt sizes","T-shirt sizing"]},{"id":"poker","g":"plan","word":"Poker-ka qorshaynta (Planning poker)","text":"Ciyaar lagu qiyaaso: qof walba wuxuu isla mar muujiyaa kaar cabbir ah, kaddib kan ugu sarreeya iyo kan ugu hooseeya ayaa sharxa sababta.","also":["Scrum poker","planning poker"]},{"id":"dependency","g":"plan","word":"Ku tiirsanaan (Dependency)","text":"Marka qayb shaqo aysan bilaabmi karin ama dhammaan karin ilaa mid kale dhammaato.","also":["dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Xannibaad (Blocker)","text":"Wax kasta oo hadda shaqada ka celinaya inay horay u socoto, sida jawaab maqan ama qalab xumaaday.","also":["blocker","blockers"]},{"id":"deadline","g":"plan","word":"Taariikhda kama dambaysta ah (Deadline)","text":"Taariikhda ay tahay in wax la dhammeeyo ka hor.","also":["deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Wax la gaarsiiyo (Deliverable)","text":"Wax dhab ah oo shaqadu soo saarto oo la gacan geliyo, sida bog shaqeynaya ama warbixin.","also":["deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Saadaal (Forecast)","text":"Saadaasha waxa u badan inay dhacaan, sida goorta shaqadu dhammaan doonto, iyadoo lagu salaynayo waxa aad ilaa hadda taqaano.","also":["forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Cabbir (Metric)","text":"Wax kasta oo aad cabbirto oo aad waqti ka daba socoto, sida booqashooyinka bogga ama waqtiga ay qaadato hagaajin.","also":["metric","metrics"]},{"id":"feedback","g":"plan","word":"Jawaab celin (Feedback)","text":"Waxa dadku kuu sheegaan oo ku saabsan shaqadaada, wanaag iyo xumaanba. Helitaankeeda goor hore oo had iyo jeer waa wadnaha Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Liiska sugitaanka ee fikrado iyo shaqo aan weli la qorshayn, kan ugu muhiimsan ayaa ugu sarreeya. Waxba halkaas looma shaqeeyo ilaa ay u dhaqaaqdo Waxa la sameeyo."},{"id":"sprint","g":"agile","word":"Sprint","text":"Muddo gaaban oo go'an oo shaqo ah (badanaa hal ama laba usbuuc, oo aan marna ka badnayn bil) oo leh hadaf iyo kaarar la isku raacay in la dhammeeyo.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Isu-imaatin degdeg ah oo maalinle ah: waxa xubin kastaa qabatay, waxa ay xigta qaban doonto, iyo waxa hor istaagaya. Scrum-ka waxaa loogu yeeraa daily scrum.","also":["stand-up","standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Hab shaqo oo kaararku ku dhex socdaan tiirarka board (sida Waxa la sameeyo, Socda, La dhammeeyay) kooxduna ay xaddiddo inta hal mar socota, si shaqadu u sii socoto."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP waa gaabinta work in progress. Xadka WIP waa inta ugu badan ee kaarar ah ee tiir ay tahay inuu hal mar hayo, si kooxdu u dhammayso waxyaabaha ka hor inta aysan bilaabin kuwo kale.","also":["WIP"]},{"id":"dod","g":"agile","word":"Qeexidda La dhammeeyay","text":"Liiska gaaban ee kooxda ee waxa “dhammaaday” macnaheedu yahay, sida la tijaabiyay oo la sharraxay, ka hor inta kaar laguu dhiibin. Mataanaheeda, Qeexidda Diyaar, waxay sheegtaa goorta kaar ku filan yahay in la bilaabo.","also":["Definition of Ready","DoD","DoR","Qeexidda Diyaar"]},{"id":"retro","g":"agile","word":"Dib-eegis","text":"Dib u eegis joogto ah oo lagu eego sida kooxdu u shaqayso, si loo isku raaco hal ama laba wax oo marka xigta si ka wanaagsan loo sameeyo. Waa gaabinta retrospective. AI-gile dhexdiisa dib-eegisku wuxuu soo jeediyaa isbeddel ku yimaada habka shaqada kooxda, adiguna waxaad dhahdaa Go ama Wali maya.","also":["retro","retrospective","dib-eegisyo"]},{"id":"swarm","g":"agile","word":"Koox wada shaqeysa","text":"Gacmo oo dhan ha la isugu yimaado: dad badan ayaa shaqooyin kale dhinac iska dhiga si ay hal arrin degdeg ah u wada hagaajiyaan ilaa la xalliyo. AI-gile dhexdiisa koox kastaa waxay ka caawisaa hal mashruuc, mashaariicda kalena way sugaan inta lagu jiro.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Scrum dhexdiisa, qofka kooxda ka caawiya inay si fiican u shaqayso: ka saara waxa hor istaaga, kulamada ku haya jidka saxda ah, oo bara caadooyin wanaagsan, isagoon cidna amar ku dul fulin. AI-gile dhexdiisa Lead Scrum Master wuxuu arkaa kaararka xayiran, wuu dhiirrigeliyaa kooxaha, wuxuuna ku xasuusiyaa waxa sugaya, mashruuc kasta.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Hab shaqo oo tillaabooyin yaryar ah: wax yar dhis, natiijooyin dhab ah had iyo jeer tus, wax ka bar waxa dadku yidhaahdaan oo qorshaha beddel marka aad socoto, halkii wax walba hore loo qorsheeyo.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Axdiga Agile (Agile Manifesto)","text":"Bayaan gaaban oo sanadkii 2001 ay qoreen dad software sameeya. Wuxuu dadka, natiijooyinka shaqeeya, la shaqaynta dhow ee macaamiisha iyo ka jawaabidda isbeddelka ka hormariyaa qorshayaal culus iyo waraaqo badan.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Habka hore ee shaqada: wax walba qorshee, kaddib dhammaan dhis, kaddib dhammaan tijaabi, hal marxalad kadib tan kale. Isbeddellada goor dambe yimaada way adag yihiin, waana qaali.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Wareeg (Iteration)","text":"Hal wareeg oo wax lagu dhisayo, lagu hubinayo oo lagu hagaajinayo. Shaqada Agile waa silsilad kuwan ah, sprint-kuna waa hal nooc oo ka mid ah.","also":["iteration","iterations"]},{"id":"increment","g":"agile","word":"Kordhin (Increment)","text":"Qayb cusub oo shaqeysa oo alaabta lagu daray sprint ama wareeg shaqo, oo la jaanqaadaya waxa hore u jiray.","also":["increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Hab Agile oo caan ah: koox yar ayaa hadaf ugu shaqaysa sprint-yo gaagaaban, iyadoo leh doorar go'an iyo dhawr kulan oo joogto ah oo lagu qorsheeyo, lagu hubiyo lagana hagaajiyo."},{"id":"scrumteam","g":"agile","word":"Kooxda Scrum (Scrum team)","text":"Kooxda yar ee shaqada ka qabata Scrum: mulkiilaha alaabta, Scrum Master iyo horumariyayaasha.","also":["Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Kulamada Scrum (Scrum events)","text":"Kulamada joogtada ah ee Scrum: qorshaynta sprint-ka, scrum-ka maalinlaha ah, dib-u-eegista sprint-ka iyo retro. Dad badan waxay ugu yeedhaan ceremonies.","also":["ceremonies","Scrum ceremonies","Scrum events"]},{"id":"sprintplan","g":"agile","word":"Qorshaynta sprint-ka (Sprint planning)","text":"Kulanka bilowga sprint-ka ee kooxdu ku heshiiso sababta sprint-ku muhiimka u yahay, kaararka la qaadanayo iyo sida loo bilaabayo.","also":["sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Hadafka sprint-ka (Sprint goal)","text":"Hal jumlad oo sheegaysa waxa sprint-ku u yahay. Hawlaha yaryar way isbeddeli karaan jidka, ilaa hadafka la gaaro.","also":["sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Liiska sprint-ka (Sprint backlog)","text":"Kaararka loo doortay sprint-ka hadda socda, iyo qorshaha kooxdu u leedahay inay qabato.","also":["sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Liiska shaqada alaabta (Product backlog)","text":"Liiska buuxa ee la kala horreeyey ee wax walba oo laga yaabo in loo dhiso alaabta, kan ugu muhiimsan ayaa ugu sarreeya. Wuu isbeddelaa marka aad wax barato.","also":["product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Hadafka alaabta (Product goal)","text":"Natiijada weyn ee alaabtu u socoto, taasoo kooxda ka caawisa inay doorato waxa xiga.","also":["product goal","product goals"]},{"id":"refinement","g":"agile","word":"Hagaajinta backlog-ka (Backlog refinement)","text":"Dib u eegis joogto ah oo backlog-ka loo sameeyo si loo nadiifiyo, loo kala qaybiyo, loo kala horreeyo loona kordhiyo faahfaahin kaararka, si ay diyaar ugu noqdaan qaadasho. Waxaa sidoo kale loo yaqaan backlog grooming.","also":["backlog refinement","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Dib-u-eegista sprint-ka (Sprint review)","text":"Kulan dhammaadka sprint-ka ah oo kooxdu ku soo bandhigto waxa ay dhammaysay, kana maqasho waxa dadku ka qabaan, si loo go'aamiyo waxa xiga.","also":["sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Muujin (Demo)","text":"Muujinta shaqo dhammaatay oo shaqaynaysa, si toos ah, dadkii codsaday.","also":["demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Xad waqti (Timebox)","text":"Waqti go'an oo wax loo qoondeeyay. Marka uu dhammaado waad joogsanaysaa, xitaa haddii aan wax walba la dhammayn.","also":["timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Xawaaraha (Velocity)","text":"Inta shaqo ee kooxi badanaa ku dhammayso sprint, oo loo isticmaalo qorshaynta inta la qaadanayo marka xigta. Ma aha dhibco lagu cabbiro sida uu qofku u dadaalo.","also":["velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Awood (Capacity)","text":"Inta shaqo ee kooxdu qaadi karto muddo gudaheed, marka laga jaro fasaxyada iyo hawlaha kale.","noTip":1},{"id":"burndown","g":"agile","word":"Jaantuska dhimista (Burndown chart)","text":"Jaantus muujinaya shaqada ka hadhay sprint-ka oo maalin kasta hoos u dhacaysa. Haddii xarriiqdu siman tahay oo aysan dhaqaaqin, wax baa xayiran.","also":["burndown","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Jaantuska kordhitaanka (Burnup chart)","text":"Jaantus muujinaya shaqada dhammaatay oo waqti ka dib kordhaysa, oo ay ag taal wadarta la qorsheeyay, si aad u aragto goorta aad gaari doonto.","also":["burnup","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Boardka Kanban (Kanban board)","text":"Boardka laftiisa: tiir u ah marxalad kasta oo shaqada ka mid ah, kaararkuna way ku dhex socdaan.","also":["Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Nidaamka soo jiidashada (Pull system)","text":"Hab shaqo oo shaqo cusub la bilaabo oo keliya marka qof uu hayo meel uu ku qaado, halkii lagu riixi lahaa qof horeba u buuxa.","also":["pull system","pull-based"]},{"id":"flow","g":"agile","word":"Socodka (Flow)","text":"Sida habsami leh ee shaqadu ugu dhex socoto boardka. Socod fiican wuxuu ka dhigan yahay in kaararku sii socdaan, oyna isku tuulmin.","also":["flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Wadarta waqtiga (Lead time)","text":"Inta ay qaadato laga bilaabo marka qof wax codsado ilaa laga dhammeeyo.","also":["lead time","lead times"]},{"id":"cycletime","g":"agile","word":"Waqtiga wareegga (Cycle time)","text":"Inta uu kaar qaato laga bilaabo marka shaqadu runtii ka bilaabato ilaa uu dhammaado.","also":["cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"Inta la dhammeeyay (Throughput)","text":"Inta kaar ee la dhammeeyo usbuuc, ama muddo kasta oo go'an.","also":["throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Hakad (Bottleneck)","text":"Marxaladda keliya ee shaqadu ku urursato oo gaabisa wax walba oo ka dambeeya, sida qoorta cidhiidhiga ah ee dhalada.","also":["bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Jidka (Swimlane)","text":"Saf boardka dhex mara oo isu geeya kaarar hal nooc ah, sida shaqo degdeg ah ama kaararka hal koox.","also":["swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Hab shaqo oo meesha ka saara qashin (wax kasta oo macmiilka aan caawinayn) oo shaqada ku haya inay socoto."},{"id":"waste","g":"agile","word":"Qashin (Waste)","text":"Gudaha Lean, wax kasta oo dadaal qaata laakiin aan macmiilka caawinayn, sida sugitaan, dib u samayn ama dhisidda waxyaabo aan qofna isticmaalin.","noTip":1},{"id":"kaizen","g":"agile","word":"Hagaajin joogto ah (Continuous improvement)","text":"In yar laga sii fiicnaado had iyo jeer iyadoo la samaynayo isbeddello yaryar oo joogto ah, kaddibna la hubinayo inay wax tareen. Dib-eegisyadu (retros) waa hal hab oo loo sameeyo. Waxaa kaloo la yiraahdaa kaizen.","also":["continuous improvement","kaizen"]},{"id":"selforg","g":"agile","word":"Koox is-habeysa (Self-organising team)","text":"Koox iyadu go'aamisa sida shaqada loo qabanayo, halkii tallaabo tallaabo loogu sheegi lahaa.","also":["self-organising team","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Koox xirfado badan leh (Cross-functional team)","text":"Koox haysata dhammaan xirfadaha ay u baahan tahay si ay shaqada iyadu u dhammaysato, sida naqshadaynta, dhisidda iyo tijaabinta.","also":["cross-functional team","cross-functional"]},{"id":"spike","g":"agile","word":"Baaritaan gaaban (Spike)","text":"Cilmi-baadhis gaaban oo waqti xaddidan, lagu jawaabo su'aal ka hor inta aan la galin shaqada dhabta ah.","also":["spike","spikes"]},{"id":"rework","g":"agile","word":"Dib u samayn (Rework)","text":"Shaqo mar kale la sameeyo sababtoo ah markii ugu horreysay sax ma ahayn.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Agile baaxad weyn (SAFe)","text":"Hababka loo isticmaalo Agile kooxo badan oo ku jira hay'ad weyn. SAFe (Scaled Agile Framework) waa tusaale caan ah.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Folderka koodhka mashruuca oo leh taariikhdiisa buuxda ee commit-yada. Wuxuu ku noolaan karaa kombuyuutarkaaga, GitHub, ama labadaba.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Xariiq shaqo oo gaar ah koodhka ku jira, si isbeddello loo sameeyo iyada oo aan la taaban nooca ugu weyn.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Sawir la keydiyay oo koodhka ah, oo leh qoraal gaaban oo ku saabsan waxa isbeddelay. Had iyo jeer waad ku laaban kartaa mid.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"U dirista sawirradaada la keydiyay (commits) kombuyuutarkan ilaa nuqulka la wadaago ee khadka ku jira, sida GitHub, si ay kayd ugu jiraan oo kuwa kale u helaan."},{"id":"merge","g":"build","word":"Merge","text":"Ku darista isbeddellada hal branch mid kale, badanaa dib loogu celiyo nooca ugu weyn."},{"id":"pr","g":"build","word":"Pull request","text":"Codsi ah in isbeddellada branch la hubiyo oo lagu daro nooca ugu weyn. Bogagga qaarkood waxay ugu yeeraan merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Nadiifinta koodhka iyada oo aan la beddelin waxa uu sameeyo: faylal yar yar, magacyo cad, soo noqnoqod yar."},{"id":"bug","g":"build","word":"Bug","text":"Wax aan sidii loogu talagalay u shaqaynayn.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"Indho labaad: qof aan ahayn qoraha ayaa hubiya shaqada ka hor inta aysan ku soo gaarin, si khaladaad yar oo keliya u gudbaan. AI-gile dhexdiisa AI kale ayaa hubiya kaar kasta.","also":["dib-u-eegis asxaab","code review"]},{"id":"code","g":"build","word":"Koodh (Code)","text":"Tilmaamaha la qoray ee u sheegaya kombuyuutar waxa uu sameeyo. Waxaa kaloo loo yaqaan source code.","also":["code","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Luuqadda barnaamijka (Programming language)","text":"Luuqad lagu qoro koodh, sida JavaScript, Python ama Java. Kuwa kala duwan waxay ku habboon yihiin hawlo kala duwan.","also":["programming language","programming languages"]},{"id":"developer","g":"build","word":"Horumariye (Developer, dev)","text":"Qof qora oo beddela koodh. Waxaa kaloo loo yaqaan programmer ama software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Barnaamijyada ku shaqeeya kombuyuutarada iyo taleefannada, oo ka duwan mashiinnada laftooda (hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Soo gaabinta application: barnaamij dadku u isticmaalaan inay wax ku qabsadaan, taleefan, kombuyuutar ama browser dhexdiisa.","also":["app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"App shabakadeed (Web app)","text":"App ku shaqeeya web browser, sidaas darteed waxba lama rakibayo.","also":["web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Dhinaca hore (Front end)","text":"Qaybta app-ka aad aragto oo aad riixdo: shaashadaha, badhamada iyo erayada, badanaa browser-kaaga.","also":["front end","front-end","frontend"]},{"id":"backend","g":"build","word":"Dhinaca dambe (Back end)","text":"Qaybta app-ka ee dhabarka ka shaqeysa oo kaydisa xogta oo qabata shaqada marka aad wax riixdo, sida hubinta erayga sirta ah.","also":["back end","back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Ka shaqaynta front end-ka iyo back end-ka labadaba.","also":["full stack","full-stack"]},{"id":"ui","g":"build","word":"Wajiga isticmaalaha (User interface, UI)","text":"Waxa qofku shaashadda ka arko oo uu isticmaalo: qaabeynta, badhamada, liisaska iyo qoraalka.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"Khibradda isticmaalaha (UX)","text":"Sida ay dareen ahaan u tahay isticmaalka shay: fudud, cad oo raaxo leh, ama jahwareer leh oo gaabis ah.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Helitaan loo siman yahay (Accessibility, a11y)","text":"Ka dhigidda waxyaabaha kuwo qof walba isticmaali karo, oo ay ku jiraan dadka aan si fiican wax u arki karin, aan isticmaali karin jiirka (mouse) ama isticmaala akhriyaha shaashadda.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Naqshad la qabsata shaashadda (Responsive design)","text":"Ka dhigidda bogagga inay ku habboonaadaan oo si fiican ugu shaqeeyaan cabbir kasta oo shaashad ah, laga bilaabo taleefanka ilaa shaashad weyn.","also":["responsive design"]},{"id":"designsys","g":"build","word":"Nidaamka naqshadda (Design system)","text":"Xirmo la wadaago oo ah midabyo, farta qoraalka, badhamo iyo xeerar, si shaashad kastaa isku si u muuqato oo isku si u dhaqanto.","also":["design system","design systems"]},{"id":"architecture","g":"build","word":"Dhismaha nidaamka (Architecture)","text":"Qaabka guud ee nidaam: waa maxay qaybaha ugu waaweyn iyo sida ay isula hadlaan."},{"id":"database","g":"build","word":"Kaydka xogta (Database, DB)","text":"Kayd habaysan oo macluumaad ah, sida spreadsheet aad u xooggan oo app-ku akhrin karo oo beddeli karo.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Qaabka database-ka (Schema)","text":"Qaab-dhismeedka database: miisaska macluumaadka ee uu leeyahay iyo waxa mid kasta galaya.","also":["database schema","schema"]},{"id":"sql","g":"build","word":"SQL","text":"Gaabinta structured query language: luuqadda loo isticmaalo in database badan lagu weydiiyo macluumaad ama la beddelo.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Xog (Data)","text":"Macluumaadka uu kombuyuutar kaydiyo, sida magacyada, dalabyada ama dejinta.","also":["data","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Kombuyuutar had iyo jeer shidan oo ka jawaabaya codsiyada kombuyuutarada kale, sida u dirista bog marka aad booqato.","also":["server","servers"]},{"id":"client","g":"build","word":"Client","text":"Dhinaca wax weydiista, badanaa browser-kaaga ama app-kaaga, oo la hadla server. Ganacsiga dhexdiisa, waxay sidoo kale macnaheedu tahay macmiil.","also":["client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Gaabinta application programming interface: liis go'an oo codsiyo ah oo barnaamij u diri karo barnaamij kale, sida in adeegga cimilada la weydiiyo saadaasha maanta.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Hal shay oo ku jira liiska API: cinwaan web ah oo barnaamij u yeedhi karo si uu wax u helo ama u diro.","also":["endpoints"]},{"id":"integration","g":"build","word":"Isku xirid (Integration)","text":"Isku xirka laba nidaam si ay u wada shaqeeyaan, sida dukaankaaga oo dalabyada u dira software-ka xisaabaadka.","also":["integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Fariin uu nidaam si iskiis ah ugu diro mid kale isla marka wax dhacaan, sida “lacagta waa la helay”.","also":["webhooks"]},{"id":"library","g":"build","word":"Maktabad (Library)","text":"Koodh diyaarsan oo qof kale qoray oo aad dib u isticmaali karto halkii aad adigu qori lahayd.","also":["library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework (Qaab-dhismeed)","text":"Qaab diyaarsan oo app lagu dhiso oo go'aamiya inta badan sida koodhka loo habeeyo, sida qalfoofka guriga ee aad buuxiso.","also":["framework","frameworks"]},{"id":"sdk","g":"build","word":"Sanduuqa qalabka software (SDK)","text":"Sanduuq qalab, koodh iyo tusaalayaal ah oo loogu talagalay dhisidda software hal madal ama adeeg.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Ku tiirsanaanta software","text":"Maktabad ama qalab koodhkaagu u baahan yahay si uu u shaqeeyo. Cusboonaysiintooda joogtada ah waa muhiim amniga awgiis.","also":["software dependency","software dependencies"]},{"id":"package","g":"build","word":"Xirmo (Package)","text":"Xirmo koodh diyaarsan oo aad rakibi karto oo ku isticmaali karto mashruuc.","also":["package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Maamulaha xirmooyinka (Package manager)","text":"Qalab keena oo cusboonaysiiya xirmooyinka koodhkaagu ku tiirsan yahay. npm waa mid caan ah.","also":["package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Qalabka ugu isticmaalka badan ee lagu kaydiyo taariikhda isbeddelada koodhka, sida commit-yo iyo branch-yo."},{"id":"github","g":"build","word":"GitHub","text":"Website ku haya repo-yada Git onlayn, si kooxuhu u wadaagaan koodh, dib ugu eegaan isbeddellada ugana daba galaan shaqada."},{"id":"vcs","g":"build","word":"Maamulka noocyada (Version control)","text":"Haynta taariikh buuxda oo ah isbeddel kasta oo faylasha lagu sameeyo, si aad u aragto cidda waxa beddeshay oo aad dib ugu noqon karto haddii loo baahdo. Git ayaa taas qabta.","also":["version control","source control","version control system"]},{"id":"clone","g":"build","word":"Clone (Nuqul)","text":"Samaynta nuqul buuxa oo kuu gaar ah oo repo ah, oo taariikhdiisu la socoto, kombuyuutarkaaga.","also":["clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Keenidda commit-yadii ugu dambeeyay ee nuqulka la wadaago (sida GitHub) oo la keeno kombuyuutarkaaga. Waa lidka push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch (Laanta ugu weyn)","text":"Nooca rasmiga ah ee koodhka oo qof walba ka shaqeeyo, badanaa loo yaqaan main ama master.","also":["main branch","master branch"]},{"id":"conflict","g":"build","word":"Iskhilaafka merge-ka (Merge conflict)","text":"Marka laba isbeddel ay si kala duwan u taabtaan isla sadarrada, kombuyuutarkuna uusan isku dari karin, oo qof ay tahay inuu doorto.","also":["merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (Farqi)","text":"Muuqaal muujinaya sida saxda ah waxa isbeddelay labada nooc dhexdooda: sadarrada lagu daray iyo kuwa laga qaaday.","also":["diff","diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Nuqulkaaga repo-ga qof kale, oo aad beddeli karto adigoon saameynin kiisa.","also":["fork","forks","forked"]},{"id":"script","g":"build","word":"Script","text":"Barnaamij gaaban oo iskiis u qabta hal shaqo, sida nadiifinta faylasha ama bilaabidda app-ka.","also":["script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Build (Dhis)","text":"U beddelidda koodhka wax diyaar u ah in lagu shaqeeyo, ama natiijada diyaarka ah lafteeda.","also":["build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Tarjumidda koodhka dadku qoreen oo loo beddelo qaab kombuyuutarku si toos ah u socodsiin karo.","also":["compile","compiler"]},{"id":"cli","g":"build","word":"Sadarka amarka (CLI)","text":"Daaqad qoraal ah oo aad ku qorto tilmaamaha kombuyuutarka halkii aad riixi lahayd. Waxaa kaloo loo yaqaan terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Habayn (Configuration, config)","text":"Dejinta xakamaysa sida software-ku u dhaqmo, oo laga sooco koodhka si ay u fududaato in la beddelo.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"Dejin barnaamij la siiyo markuu bilowdo, badanaa loo isticmaalo cinwaanno ama erayo sir ah si aan loogu qorin koodhka.","also":["environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Ka saarista khaladaadka (Debugging)","text":"Raadinta sababta wax u shaqeyn waayeen, iyo hagaajinteeda.","also":["debugging","debug","debugged"]},{"id":"pairing","g":"build","word":"Barnaamij laba qof (Pair programming)","text":"Laba qof (ama qof iyo AI) oo isla koodh ku wada shaqeeya, mid qoraya, midna hubinaya.","also":["pair programming","pairing"]},{"id":"docs","g":"build","word":"Dukumeentiyo (Documentation, docs)","text":"Sharraxaado la qoray oo ku saabsan sida wax u shaqeeyaan ama sida loo isticmaalo.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Faylka ugu horreeya ee la akhriyo repo gudihiisa: waa maxay mashruuca iyo sida loo shaqaysiiyo.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Nidaam hore (Legacy system)","text":"Nidaam da' weyn oo weli la isticmaalo oo adag in la beddelo, badanaa sababtoo ah dad yar ayaa weli fahma.","also":["legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Daynta farsamo (Technical debt)","text":"Jid-gaabyo hadda waqti badbaadiya laakiin isbeddellada dambe ka dhiga kuwo gaabis ah, sida deyn ribadeedu korayso. Refactoring ayaa dib u bixisa.","also":["technical debt","tech debt"]},{"id":"test","g":"test","word":"Test","text":"Hubin in wax u shaqeeyaan sidii ay ahayd. Tijaabooyinka qaarkood kombuyuutarka ayaa iskiis u socodsiiya mar kasta oo koodhka la beddelo; kuwa kale waa adiga oo tijaabinaya kaar dhammaaday ka hor intaadan aqbalin.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Gaabinta quality assurance: wax kasta oo la sameeyo si loo hubiyo in shaqadu sax tahay ka hor intaanay toos noqon. Gudaha AI-gile macnaheedu waa hubinta otomaatigga ah: marka QA casaan tahay, wax baa fashilmay, mana toos noqon karto ilaa la hagaajiyo.","also":["hubinta tayada","xaqiijinta tayada"]},{"id":"testpile","g":"test","word":"Xirmada tijaabada","text":"Kaarrada la dhammeeyay ee sugaya inaad tijaabiso, mid mid. Mid aqbal ama dib ugu celi qoraal, kan xigaana wuu soo baxayaa.","also":["xirmooyinka tijaabada"]},{"id":"autotest","g":"test","word":"Tijaabo otomaatig ah (Automated test)","text":"Hubin kombuyuutarku laftiisa socodsiiyo mar kasta oo koodhka la beddelo, si khaladaadka goor hore loo qabto.","also":["automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Tijaabo gacanta (Manual test)","text":"Qof gacanta ku tijaabinaya shaqada si uu u arko inay u dhaqmayso sidii ay lahayd.","also":["manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"Hubin otomaatig ah oo yar oo ku saabsan hal qayb oo koodh ah oo keligeed ah.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Tijaabada isku xirka (Integration test)","text":"Hubin in qaybo badan ay si fiican u wada shaqeeyaan, ee aan ahayn mid mid keliya.","also":["integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Tijaabada bilow-ilaa-dhammaad (E2E)","text":"Tijaabo u dhaqanta sidii isticmaale dhab ah bilow ilaa dhammaad, sida is-diiwaangelin, iibsasho iyo lacag bixin.","also":["E2E","end-to-end test","end-to-end tests"]},{"id":"uat","g":"test","word":"Tijaabada aqbalidda isticmaalaha (UAT)","text":"Dadkii shaqada codsaday ayaa iyagu tijaabiya oo sheega inay qabato waxa ay u baahan yihiin. Kaararka tijaabada ee AI-gile ayaa ah nooceeda tan.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Dib-u-dhac (Regression)","text":"Wax hore u shaqaynayay laakiin jabay kadib isbeddel. Tijaabooyinka regression waxay hubiyaan in waxyaabihii hore weli shaqaynayaan.","also":["regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test (Tijaabo degdeg ah)","text":"Hubin aad u degdeg ah oo lagu eego in waxyaabaha ugu muhiimsan ay xitaa shaqaynayaan, tusaale ahaan isla marka isbeddel la daah-furo. Haddii ay fashilanto, jooji oo eeg.","also":["smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"Tijaabo sahan (Exploratory testing)","text":"Tijaabinta alaabta si xor ah iyo baarista siyaabo kala duwan, si loo helo dhibaatooyin ay hubinnada la qorsheeyay seegi lahaayeen.","also":["exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Kiis tijaabo (Test case)","text":"Hal xaalad la qoray oo la tijaabiyo: tillaabooyinka, iyo waxa ay tahay inay dhacaan.","also":["test case","test cases"]},{"id":"coverage","g":"test","word":"Baaxadda tijaabada (Test coverage)","text":"Inta koodhka ah ee ay hubiyaan tijaabooyin otomaatig ahi. Inta badan ayaa badanaa ammaan badan, laakiin baaxad sare keligeed ma caddayso in koodhku si fiican u shaqeeyo.","also":["test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Xogta tijaabada (Test data)","text":"Macluumaad tusaale ah oo la sameeyay oo tijaabada lagu isticmaalo, si aan loo bandhigin faahfaahinta gaarka ah ee qof dhab ah.","also":["test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Xaalad xad (Edge case)","text":"Xaalad aan caadi ahayn oo xadka ku taal, sida foom madhan ama magac leh apostrophe, halka wax badanaa ku jabaan.","also":["edge case","edge cases"]},{"id":"happypath","g":"test","word":"Wadada farxadda (Happy path)","text":"Waddada caadiga ah ee wax walba si fiican u dhacaan. Tijaabin wanaagsan waxay sidoo kale isku daysaa waddooyinka aan sidaas ahayn."},{"id":"perftest","g":"test","word":"Tijaabada waxqabadka (Performance testing)","text":"Hubinta inta uu wax dhakhso yahay iyo sida uu ula qabsado culayska.","also":["performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Tijaabada culeyska (Load testing)","text":"Hubinta sida nidaam u dulqaato marka dad badan isla mar isticmaalaan.","also":["load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Tijaabada amniga (Security testing)","text":"Raadinta daciifnimo u oggolaan karta qof inuu si khaldan u isticmaalo nidaam ama arko waxa aanu xaq u lahayn inuu arko.","also":["security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Tijaabada helitaanka (Accessibility testing)","text":"Hubinta in dadka awoodo kala duwan leh ay alaabta isticmaali karaan, oo ay ku jirto akhriyaha shaashadda ama kiiboodh keliya.","also":["accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Hubin otomaatig ah oo ogaata khaladaadka u badan iyo qaabka aan nadiifka ahayn ee koodhka, sida hubiyaha higaadda ee barnaamijyada.","also":["linter","lint"]},{"id":"static","g":"test","word":"Falanqaynta static (Static analysis)","text":"Hubinta dhibaatooyinka koodhka iyadoo si otomaatig ah loo akhrinayo, iyadoon la socodsiin.","also":["static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Tijaabo aan xasilloonayn (Flaky test)","text":"Tijaabo mararka qaarkood gudubta mararka qaarkoodna fashilanta sabab cad la'aan, sidaas darteed aan si buuxda loo aamini karin.","also":["flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Dib u soo saar (Reproduce, repro)","text":"Ula kac in bug mar kale la keeno iyadoo la raacayo isla tillaabooyinkii, si loo darso oo loo hagaajiyo. Qorista tillaabooyinkaas waa qaybta ugu waxtarka badan warbixinta bug-ga.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Darnaanta (Severity)","text":"Inta ay le'eg tahay saamaynta xun ee dhibaato, laga bilaabo carqalad yar ilaa wax walba joogsadaan.","also":["severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Koobiyaynta nooc cusub oo software ah oo la geliyo kombuyuutarada socodsiiya, sida nuqul tijaabo ama adeegga toosan."},{"id":"release","g":"change","word":"Sii deyn","text":"Xirmo magac leh oo shaqo dhammaatay ah oo wada toos u baxda, oo leh qoraallo gaaban oo ku saabsan waxa isbeddelay. 🚀 Sii deynta waxay qoraallada ka qortaa kaarrada la dhammeeyay.","also":["sii deynta","release"]},{"id":"rollback","g":"change","word":"Dib u celin","text":"Ku noqoshada nooca ugu dambeeyay ee shaqeynayay marka mid cusub dhibaato keeno. Gudaha AI-gile, Dib u celin wuxuu isku soo ururiyaa tillaabooyinka laabashada ee isbeddel kasta lagu qoray hal liis hubin.","also":["rollback","dib u celi","dib loo celiyay"]},{"id":"live","g":"change","word":"Toos","text":"Nooca dhabta ah ee dadku isticmaalaan, oo ka duwan nuqul wax lagu tijaabiyo. Horumarinta waxay sidoo kale u yaqaanaan production.","also":["live","production","wax-soo-saar"],"noTip":1},{"id":"change","g":"change","word":"Isbeddel","text":"Isbeddel la qorsheeyay oo lagu sameynayo wax dadku ku tiirsan yihiin, oo marka hore la qoray: maxay, sababta, khatarta, goorta iyo sida looga noqon karo. Ku bilow 🔀 Soo bandhig isbeddel.","also":["isbeddello","codsi isbeddel","codsiyo isbeddel"],"noTip":1},{"id":"risk","g":"change","word":"Khatar","text":"Wax khaldami kara, oo lagu qiimeeyay inta ay u badan tahay iyo inta ay xumaan lahayd. ⚠️ Khataro waxay ku hayaan hal liis, dhibcaha ugu sarreeya marka hore, mid kasta oo leh taariikh dib loogu eego.","also":["khataro","diiwaanka khatarta"]},{"id":"chgwin","g":"change","word":"Daaqad isbeddel","text":"Waqtiyada isbeddelladu toos u bixi karaan, sida fiid Talaado ah oo deggan. Daaqadda dibaddeeda kaar isbeddel lama dhammeyn karo, haddii aanay ahayn xaalad degdeg ah.","also":["daaqadaha isbeddelka","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Hubin ugu dambaysa wax yar ka hor inta aan isbeddel la daah-furin: qof kasta oo ay tahay inuu oggolaado wuxuu yiraahdaa Go ama No go. Wuxuu hore u socdaa oo keliya marka qof walba yiraahdo Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Oggolaansho","text":"Sugidda haa kahor inta shaqadu aanay bilaabmin. Kaar saaxiib soo gudbiyay, ama isbeddel, wuxuu ku sugayaa ✅ Oggolaanshaha ilaa aad oggolaato ama diido.","also":["oggolaanshaha","oggolow"]},{"id":"quiettime","g":"change","word":"Waqti aamusnaan","text":"Muddo waqti ah, sida inta lagu jiro live stream, demo ama habeenka, marka aan waxba toos la dhigin. Kooxuhu way sii shaqeeyaan oo tijaabiyaan, laakiin toos-noqoshadu waxay sugtaa ilaa ay dhammaato. Meelo kale waxaa loo yaqaan change freeze.","also":["waqtiyada aamusnaanta","joojinta isbeddelka","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Hab shaqo oo dadka dhisa software-ka iyo dadka socodsiiya ay hal koox ahaan u shaqeeyaan, iyagoo otomaatig badan isticmaalaya, si isbeddelladu u daah-furmaan marar badan oo si ammaan ah."},{"id":"cicd","g":"change","word":"CI/CD (isku darid iyo gaarsiin joogto ah)","text":"Isbeddellada qof walba si joogto ah ayaa loogu daraa nooca ugu weyn oo si otomaatig ah loo hubiyaa mar kasta (continuous integration), si software-ku mar walba diyaar ugu ahaado in la daah-furo marka badhan la riixo (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Deployment joogto ah (Continuous deployment)","text":"Hal tillaabo ka sii fog continuous delivery: isbeddel kasta oo hubinta ka gudba wuxuu iskiis u noqdaa toos, iyadoon badhan la riixayn.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline (Tuubbo)","text":"Silsiladda tillaabooyinka otomaatig ah ee isbeddelku maro intuu u socdo toos, sida build, tijaabo, kaddibna deploy.","also":["pipeline","pipelines"]},{"id":"environment","g":"change","word":"Deegaan (Environment)","text":"Hal nuqul oo nidaamka ah oo gooni ah oo hal ujeeddo loogu talagalay, sida mid wax lagu dhiso, mid lagu tijaabiyo iyo kan toos ah.","also":["environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Deegaanka horumarinta (Development environment)","text":"Nuqulka horumariyuhu ka shaqeeyo, badanaa kombuyuutarkiisa, halkaas oo jebinta waxyaabaha aysan cidna waxyeello u geysan.","also":["development environment","dev environment"]},{"id":"testenv","g":"change","word":"Deegaanka tijaabada (Test environment)","text":"Nuqul gooni ah oo nidaamka ah oo loo isticmaalo tijaabo oo keliya, si adeegga dhabta ah aan loo taaban.","also":["test environment","test environments"]},{"id":"staging","g":"change","word":"Staging","text":"Nuqul ugu dambeeya oo loo diyaariyay si la mid ah kan toosta ah, oo loogu talagalay hubinta ugu dambaysa ka hor inta aan isbeddel la daah-furin.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact (Wax la dhisay)","text":"Faylka ama xirmada build soo saaro, oo diyaar u ah in la kaydiyo, la hubiyo ama toos laga dhigo.","also":["build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix (Hagaajin degdeg ah)","text":"Hagaajin degdeg ah oo si dhakhso ah toos loo dhigo, qorshaha caadiga ah ka baxsan, sababtoo ah wax muhiim ah ayaa jabay.","also":["hotfix","hotfixes"]},{"id":"patch","g":"change","word":"Patch (Hagaajin yar)","text":"Cusboonaysiin yar oo hagaajisa bug ama xirta god amni. Ku rakibidda patch-yada amniga si degdeg ah waa muhiim.","also":["patch","patches","security patch","security patches"]},{"id":"version","g":"change","word":"Lambarka nooca (Version number)","text":"Calaamad sida 2.4.1 oo sheegaysa sii deynta aad haysato. Badanaa lambarka koowaad wuxuu isbeddelaa marka isbeddello waaweyn dhacaan, kan ugu dambeeyana hagaajinno yaryar.","also":["version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Qoraalka sii deynta (Release notes)","text":"Liis gaaban oo fudud oo ah waxa ku isbeddelay sii deyn, oo loogu talagalay dadka isticmaala, oo ay ku jiraan hagaajinno iyo xadadka la yaqaan. Waxaa kaloo loo yaqaan changelog.","also":["release notes","changelog","change log"]},{"id":"flag","g":"change","word":"Calaamadda sifada (Feature flag)","text":"Fure shid-demis ah oo sifo loogu talagalay, si shaqo cusub loo daah-furo iyadoo qarsoon kaddibna la shido (ama mar kale la demiyo) iyadoon sii deyn cusub la samayn.","also":["feature flag","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Horay u gudub (Roll forward)","text":"Hagaajinta sii deyn xun adigoo si degdeg ah u soo saaraya nooc cusub oo la sixay halkii aad dib ugu noqon lahayd kii hore.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release (Sii deyn koox yar)","text":"Isbeddel marka hore koox yar loo daah-furo, qof walbana kaliya marka ay u muuqato inuu fiican yahay. Waxaa lagu magacaabay shimbirrada canary ee macdan-qodayaashu dhulka hoostiisa u qaadan jireen digniin hore ahaan.","also":["canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Haynta laba nuqul oo nidaamka toosan oo dadka hal mar loogu wareejiyo kan cusub, si aad isla markiiba dib ugu laabto haddii ay khaldanto.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Deployment joogsi la'aan (Zero-downtime deployment)","text":"Daah-furidda nooc cusub iyadoon adeeggu marna u joogsan isticmaalayaashiisa.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Fududaynta isbeddelka (Change enablement)","text":"Ka caawinta isbeddellada inay guulaystaan: miisaaminta khatarta, helitaanka oggolaanshaha saxda ah iyo doorashada waqti ku habboon. Waxaa kaloo loo yaqaan change management.","also":["change enablement","change management"]},{"id":"cab","g":"change","word":"Guddiga la talinta isbeddelka (CAB)","text":"Koox dib u eegta isbeddellada muhiimka ah oo go'aamisa haddii iyo goorta ay hore u socon karaan.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Isbeddel la cayimay (Standard change)","text":"Isbeddel khatar yar oo mar kasta loo sameeyo hab isku mid ah oo la tijaabiyay, sidaas darteed hore ayaa loo oggolaaday.","also":["standard change","standard changes"]},{"id":"normchange","g":"change","word":"Isbeddel caadi ah (Normal change)","text":"Isbeddel u baahan in la hubiyo oo la oggolaado ka hor inta aan la samayn.","also":["normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Isbeddel degdeg ah (Emergency change)","text":"Isbeddel ay tahay inuu isla markiiba dhaco si loo hagaajiyo ama looga hortago dhibaato daran, oo leh oggolaansho dhakhso ah oo la jaanqaadaya.","also":["emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Otomaatig (Automation)","text":"Ka dhigidda kombuyuutarka inuu laftiisa qabto hawl soo noqnoqota, si ay u dhakhso badato oo mar kasta si isku mid ah loo sameeyo.","also":["automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Kaabayaasha (Infrastructure)","text":"Mashiinnada, shabakadaha iyo adeegyada software-ku ku shaqeeyo.","also":["infrastructure","infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Sharaxidda server-yadaada iyo dejintooda faylal lala kaydiyo koodhka, si mar kasta loogu dhiso si isku mid ah.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Cloud (Daruur)","text":"Kiraysiga kombuyuutaro, kayd iyo adeegyo shirkad weyn iyadoo internetka loo marayo, halkii aad adigu lahaan lahayd mashiinnada.","also":["cloud","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Bixiyaha cloud-ka (Cloud provider)","text":"Shirkad internetka ku kiraysa awood kombuyuutar, sida Amazon Web Services (AWS), Microsoft Azure ama Google Cloud.","also":["cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hosting (Martigelin)","text":"Meesha app-kaaga ama website-kaagu ku nool yahay oo ku shaqeeyo si dadku u gaari karaan, badanaa laga kiraysto shirkad.","also":["hosting"]},{"id":"domain","g":"change","word":"Magaca domain-ka (Domain name)","text":"Cinwaanka web ee dadku qoraan, sida example.com. Waxaad ku kiraysataa sannad kasta, sidaas darteed waa in la cusboonaysiiyo.","also":["domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Gaabinta domain name system: buugga cinwaannada internetka, oo magac sida example.com u beddela cinwaanka kombuyuutarka saxda ah.","also":["domain name system"]},{"id":"container","g":"change","word":"Container (Weel)","text":"Xirmo xiran oo haysa app iyo wax walba oo uu u baahan yahay, si uu isku si ugu shaqeeyo kombuyuutar kasta. Docker waa qalabka ugu caansan.","also":["container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Mashiin khayaali ah (Virtual machine, VM)","text":"Kombuyuutar male ah oo ku dhex shaqeeya kombuyuutar dhab ah, si hal mashiin weyn u noqon karo kuwo badan.","also":["VM","VMs","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Socodsiinta koodh adigoon adigu daryeelin wax server ah: bixiyuhu wuu socodsiiyaa marka loo baahdo, adna waxaad bixisaa waxa aad isticmaasho."},{"id":"lb","g":"change","word":"Qaybiyaha culeyska (Load balancer)","text":"Wax booqdayaasha u kala qaybiya dhawr server, si midna uusan u culaysan.","also":["load balancer","load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"Kayd ku dhow oo haya natiijooyinkii dhawaa, si aan isla shayga mar kale loo keenin ama loo xisaabin. Nadiifintiisu waxay hagaajin kartaa bogag u muuqda kuwo duugoobay.","also":["cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Shabakadda gaarsiinta (CDN)","text":"Server-yo adduunka ku fidsan oo haya nuqullo bogaggaaga iyo sawirradaada meel u dhow booqdayaashaada, si ay dhakhso ugu furmaan.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Guuris (Migration)","text":"Ka guurinta xog ama nidaamyo habayn hore una guurinta mid cusub, ama beddelidda si taxadar leh ee sida database loo habeeyay.","also":["migration","migrations","database migration"]},{"id":"service","g":"run","word":"Adeeg","text":"Wax aad dhistay oo dadku ku tiirsan yihiin, sida website ama app, oo la daryeelo si uu u sii shaqeeyo. Calaamadee “Mashruucan waa adeeg” oo sheeg waxa uu bixiyo, cidda isticmaasha iyo cidda xilka haysa.","also":["adeegyo","service"]},{"id":"uptimepct","g":"run","word":"Waqtiga shaqada (Uptime)","text":"Inta waqti ee adeeggu shaqaynayo, badanaa boqolkiiba. 99.9% weli waxay oggolaanaysaa qiyaastii 43 daqiiqo oo joogsi ah bishii.","also":["uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"Hubinta shaqeynta","text":"Hubin otomaatig ah, dhowr daqiiqo kasta, in adeeggaagu weli jawaabayo. Haddii ay dhowr jeer oo xiriir ah fashilanto, AI-gile waxay iskeed u furtaa kaar shil.","also":["uptime checks"]},{"id":"statuspage","g":"run","word":"Bogga xaaladda","text":"Bog dadweyne oo muujinaya in adeeg shaqeynayo iyo in kale (cagaar, oranji ama casaan) oo leh warkii ugu dambeeyay, si dadka isticmaala ay iska eegaan halkii ay weydiin lahaayeen.","also":["bogagga xaaladda","status page"]},{"id":"desk","g":"run","word":"Miiska adeegga","text":"Meesha ay yimaadaan su'aalaha iyo warbixinnada dadka isticmaala adeeggaaga. AI-gile mid kasta wuxuu u kala saaraa codsi, shil ama fikrad, wuxuuna sheegaa marka ay u egtahay wax hore loo soo sheegay.","also":["desk","miiska caawimada","helpdesk","service desk"]},{"id":"svcrequest","g":"run","word":"Codsi adeeg","text":"Marka qof codsado wax caadi ah, sida akoon cusub ama caawimo yar, halkii uu ka sheegi lahaa in wax jabeen. Wuxuu sugaa doorkiisa; shilku ayaa ka horreeya.","also":["codsiyada adeegga","codsi","service request"]},{"id":"incident","g":"run","word":"Shil","text":"Wax jabay ama aan si fiican ugu shaqaynayn dadka hadda isticmaalaya, sida website-ka oo istaagay ama aad u gaabis ah. Kaarka shilka 🔥 wuxuu ka booda safka: in mar kale la shaqaysiiyo ayaa ka horreeya.","also":["shilal","incident","dhacdo"]},{"id":"major","g":"run","word":"Shil weyn","text":"Shil weyn: dad badan ayaa saameeyay, ama lacag ama xog ayaa khatar ku jira. Hal badhan ayaa koox kasta ku dhejiya (koox wada shaqeysa), toosiya cidda xilka haysa, oo codsada war xaaladeed 30 daqiiqo kasta.","also":["shilal waaweyn","major incident","dhacdo weyn"]},{"id":"oncall","g":"run","word":"Xilka qaadid","text":"Inaad noqoto qofka jawaaba marka wax jabaan, xitaa habeenkii. Adeeg kasta wuxuu leeyahay xubin koox oo xilka haysa oo marka hore la toosiyo shilalkiisa.","also":["xilka haya","on call","on-call"]},{"id":"replyby","g":"run","word":"Waqtiga jawaabta","text":"Inta kaar sugi karo jawaabta koowaad, tusaale ahaan saacad shil ahaan. Kadib wuxuu helaa saacad casaan ah, si aan waxba si aamusnaan ah loo illaawin. Waxaa kale oo loo yaqaan bartilmaameedka jawaabta.","also":["waqtiyada jawaabta","bartilmaameedka jawaabta"]},{"id":"postmortem","g":"run","word":"Dib-u-eegis shil","text":"Dib u eegis gaaban kadib shil: waxa dhacay, waxa caawiyay iyo waxa la beddelayo, iyadoo aan qofna la eedeynin. Shil lama xiri karo la'aanteed. Inta badan waxaa loo yaqaan post-mortem.","also":["post-mortem","postmortem","dib-u-eegista shilka"]},{"id":"problem","g":"run","word":"Dhibaato","text":"Sababta qarsoon ee ka dambeysa hal shil ama ka badan. Kaar 🧩 dhibaato ah wuxuu isku keenaa shilalka soo noqnoqda, si sababta loo helo oo weligeed loo hagaajiyo.","also":["dhibaatooyin","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Sababta aasaasiga ah","text":"Sababta dhabta ah ee wax u jabeen, ma aha oo keliya waxa aad aragtay inay khaldameen. Hagaaji sababta aasaasiga ah, shilkuna wuu joojiyaa soo noqoshada.","also":["sababaha aasaasiga ah","root cause"]},{"id":"workaround","g":"run","word":"Xal ku meel gaar ah","text":"Hab lagu sii shaqeysiiyo waxyaabaha ilaa hagaajinta dhabta ahi diyaar noqoto, sida dib u kicinta wax marka uu xayirmo. Waxaa lagu qoraa kaarka dhibaatada si aan qofna u baahan inuu mar kale ogaado.","also":["xalal ku meel gaar ah","workaround"]},{"id":"knownerror","g":"run","word":"Khalad la yaqaan","text":"Dhibaato sababteeda la fahmay laakiin weli aan la hagaajin, badanaa leh xal ku meel gaar ah oo la qoray. 🧩 Khaladaadka la yaqaan ayaa liis gareeya, si qof walba u isticmaalo xalka ku meel gaarka ah halkii mar kale la qodi lahaa.","also":["khaladaadka la yaqaan","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Tilmaamo tallaabo-tallaabo ah oo lagu hagaajiyo nooc dhibaato la yaqaan, si mar kasta isku si oo degdeg ah loo sameeyo. Kadib shil weyn kooxdu waxay kuu soo jeedin kartaa mid aad oggolaato.","also":["runbooks","tilmaamaha shaqada"]},{"id":"ci","g":"run","word":"Alaab habayn","text":"Hal shay oo adeeggaagu ku tiirsan yahay, sida server, domain, shahaado, fure ama shirkad wax bixisa. 🗂️ Alaabta habaynta waxay u taxdaa adeeg kasta, si aad u aragto waxa shil saameeyo iyo waxa u baahan cusboonaysiin ama kayd.","also":["alaabta habaynta","configuration item"]},{"id":"expiry","g":"run","word":"Taariikhda dhicitaanka","text":"Taariikhda uu wax joogsado haddii aan la cusboonaysiin, sida shahaadada amniga ee website ama cinwaankiisa web. AI-gile wuxuu la socdaa taariikhahan wuxuuna mid kasta u sameeyaa hal kaar oo lagu cusboonaysiiyo 30 maalmood ka hor, si aanay waxba si lama filaan ah u joogsan.","also":["taariikhaha dhicitaanka","dhicitaan","expiry"]},{"id":"backup","g":"run","word":"Kayd","text":"Nuqul la keydiyay oo xogtaada hore ah, oo lagu noqon karo haddii wax lumaan ama waxyeeloobaan. AI-gile waxay maalin kasta samaysaa kayd sabuuradahaaga.","also":["kaydad","backup","nuqul kayd"]},{"id":"restore","g":"run","word":"Soo celin","text":"Xogta oo laga soo celiyo kayd. Kayd runtii wuxuu tirsadaa marka aad ogtahay in la soo celin karo, sidaa darteed waa mudan tahay in mar mar la tijaabiyo.","also":["soo celi","la soo celiyay","restore"]},{"id":"svcreview","g":"run","word":"Dib-u-eegista adeegga","text":"Dib u eegid hal bil oo adeeg ah: shilalka la furay iyo kuwa la hagaajiyay, sida degdegga ah ee dadku jawaab u heleen, waqtiga shaqeynta iyo token-ka la isticmaalay. Dib-u-eegista bilaha ayaa tan u muujisa adeeg kasta.","also":["dib-u-eegista bilaha","service review"]},{"id":"accessreview","g":"run","word":"Dib-u-eegista galitaanka","text":"Hubinta 90 maalmood kasta cidda weli geli karta: linkiyada la wadaago, doorarka saaxiibbada, iyo erayada sirta ah iyo furayaasha la keydiyay. Mid kasta waad haynaysaa ama ka saaraysaa, si aan galitaan duug ahi u sii hadhin.","also":["access review"]},{"id":"improvements","g":"run","word":"Liiska horumarinta","text":"Wax kasta oo kooxdu go'aansatay inay ku fiicnaato, hal meel: soo jeedinta dib-eegista, hawlaha dib-u-eegista iyo hagaajinta dhibaatooyinka, mid walbana xaaladdiisa. Ka hel 📈 Horumarinta.","also":["horumarinta","improvements"]},{"id":"tokencap","g":"run","word":"Xadka token-ka","text":"Xad bil kasta ah oo ku saabsan token-ka ay wakiilada adeeggu isticmaali karaan. 80% waxaad helaysaa digniin; 100% shaqadooda gadaasha ayaa sugaysa ilaa bisha xigta ama ilaa aad xadka kor u qaaddo.","also":["xadadka token-ka","token cap"]},{"id":"svcmgmt","g":"run","word":"Maamulka adeegga (Service management)","text":"Wax walba oo ku lug leh in adeeg uu ahaado mid faa'iido leh oo u shaqeeya dadka ku tiirsan, maalin kasta.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Hage si weyn loo isticmaalo oo ku saabsan maamul adeeg oo wanaagsan, oo daboolaya waxyaabo sida shilal, dhibaatooyin iyo isbeddello. Magaca wakhti hore wuxuu u taagnaa IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Maamulka adeegga IT (ITSM)","text":"Socodsiinta teknoolajiyada sida adeeg dadka loo bixiyo, oo leh siyaabo cad oo lagu maamulo codsiyada, shilalka, isbeddellada iyo hagaajinta.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Adeeg la maamulo (Managed service)","text":"Adeeg qof kale kuu socodsiiyo oo kuu daryeelo, iyadoo heshiis lagu jiro oo ku saabsan inta uu si fiican u shaqeeyo.","also":["managed service","managed services"]},{"id":"svcowner","g":"run","word":"Mulkiilaha adeegga (Service owner)","text":"Qofka mas'uulka ka ah adeegga oo dhan: sida fiican uu u shaqeeyo, waxa uu ku kacayo iyo sida loo hagaajiyo.","also":["service owner","service owners"]},{"id":"sla","g":"run","word":"Heshiiska heerka adeegga (SLA)","text":"Ballan qoran oo macaamiisha la siiyo oo ku saabsan sida fiican adeeggu u shaqayn doono, sida “shaqaynaya 99.9% waqtiga” ama “laga jawaabo hal saac gudaheed”, badanaa lacag celin haddii la jebiyo.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Hadafka heerka adeegga (SLO)","text":"Hadafka kooxda u gaarka ah ee ku saabsan inta adeeggu si fiican u shaqayn karo muddo gudaheed, badanaa loo dejiyo wax yar ka adag SLA si loo badbaado.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Tilmaamaha heerka adeegga (SLI)","text":"Cabbirka dhabta ah ee aad hadaf la barbar dhigto, sida qaybta booqashooyinka ee si fiican u furmay.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"La heli karo (Availability)","text":"Haddii dadku adeeg isticmaali karaan marka ay u baahdaan, badanaa lagu cabbiro uptime.","also":["availability","high availability"]},{"id":"downtime","g":"run","word":"Waqtiga joogsiga (Downtime)","text":"Waqtiga adeeggu aanu shaqaynayn ama la demiyay, mid la qorsheeyay iyo mid aan la qorshayn.","also":["downtime","down time"]},{"id":"errorbudget","g":"run","word":"Miisaaniyadda khaladaadka (Error budget)","text":"Qaddarka yar ee fashil ee hadafkaaga isku halayntu oggol yahay. Inta wax ka hadhsan yihiin, waxaad khatar ku geli kartaa isbeddellada; marka dhammaan la isticmaalo, waad gaabinaysaa.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"Go'in (Outage)","text":"Waqti adeeg uu istaagay ama si xun ugu jabay isticmaalayaashiisa.","also":["outage","outages"]},{"id":"degraded","g":"run","word":"Hoos u dhacay (Degraded)","text":"Wuu shaqeynayaa, laakiin si xun: wuu gaabis yahay, ama qaybaha qaarkood ma shaqeynayaan.","also":["degraded","degraded service"]},{"id":"monitoring","g":"run","word":"La socodka (Monitoring)","text":"Si otomaatig ah oo joogto ah ula socodka adeeg, si dhibaatooyinka loo arko, waxa ugu fiican ka hor inta aysan isticmaalayaashu dareemin.","also":["monitoring"]},{"id":"observability","g":"run","word":"La arki karo (Observability)","text":"Sida fiican ee aad dibadda uga ogaan karto waxa ka socda nidaam gudihiisa, adigoo isticmaalaya log-yadiisa, tirooyinkiisa iyo trace-yadiisa.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Log (Diiwaan)","text":"Diiwaan socda oo barnaamij ka qoro waxa uu sameynayo, loo isticmaalo in lagu ogaado waxa khaldamay.","also":["log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace (Raad)","text":"Diiwaan muujinaya sida hal codsi ugu socdo qaybaha kala duwan ee nidaamka, tillaabo tillaabo, isagoo muujinaya halka uu ku gaabsaday.","also":["trace","traces","tracing"]},{"id":"latency","g":"run","word":"Daahitaan (Latency)","text":"Inta ay qaadato inuu wax jawaab bixiyo, sida sugitaanka u dhexeeya riixidda iyo soo bixidda bogga.","also":["latency"]},{"id":"alert","g":"run","word":"Digniin (Alert)","text":"Fariin otomaatig ah oo sheegaysa in wax u baahan yahay dareen, sida website-ka oo aan jawaabin.","also":["alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Daalka digniinaha (Alert fatigue)","text":"Marka digniinuhu ay aad u badan yihiin oo dadku bilaabaan inay iska indho tiraan, oo ay ku jiraan kuwa muhiimka ah.","also":["alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard (Shaashadda xogta)","text":"Shaashad muujinaysa tirooyinka iyo xaaladaha ugu muhiimsan hal mar eegid ah.","also":["dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Wicid degdeg ah (Paging)","text":"Si degdeg ah u wacidda ama u toosinta qofka shaqada u diyaarsan (on-call) dhibaato awgeed.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"Kor u qaadid (Escalation)","text":"Keenidda qof xirfad ama awood dheeraad ah leh marka arrin aan lagu xallin karin heerka hadda, ama aan si dhakhso ah loo xallin karin.","also":["escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Triage (Kala xulid)","text":"Si dhakhso ah u kala soocidda arrimaha soo galaya iyadoo loo eegayo inta ay degdeg iyo muhiim yihiin, si tan ugu xun marka hore loo qabto.","also":["triage","triaged"]},{"id":"impact","g":"run","word":"Saameyn (Impact)","text":"Inta uu wax saameeyo dadka: immisa qof, iyo sida xun.","noTip":1},{"id":"urgency","g":"run","word":"Degdeg (Urgency)","text":"Inta dhakhso ah ee ay tahay in wax laga qabto. Saamaynta iyo degdegga marka la isku daro ayaa go'aamiya mudnaanta.","noTip":1},{"id":"plevels","g":"run","word":"Heerarka mudnaanta (P1, P2…)","text":"Calaamado muujinaya inta arrin degdeg tahay. P1 waa tan ugu daran, waxayna u baahan tahay tallaabo isla markiiba.","also":["priority levels","P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Safka tigidhada (Ticket queue)","text":"Liiska codsiyada iyo shilalka sugaya in la qaado.","also":["ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Safka koowaad iyo safka labaad","text":"Heerarka taageerada: safka koowaad wuxuu qaadaa wicitaanka oo hagaajiyaa waxyaabaha fudud; safka labaadna wuxuu leeyahay xirfado qoto dheer oo loogu talagalay kuwa adag. Waxaa kaloo loo yaqaan tier 1 iyo tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Taliyaha shilka (Incident commander)","text":"Qofka keliya ee hoggaamiya ka jawaabidda shil, si qof walba u ogaado cidda go'aamisa iyo cidda waxa qabanaysa.","also":["incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Waqtiga jawaabta (Response time)","text":"Inta ay qaadato ka hor inta qof uusan markii ugu horreysay qaadan codsi ama shil.","also":["response time","response times"]},{"id":"resolution","g":"run","word":"Waqtiga xallinta (Resolution time)","text":"Inta ay qaadato in si buuxda loo xalliyo codsi ama shil, laga bilaabo marka la soo sheego ilaa la hagaajiyo.","also":["resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Celceliska waqtiga soo kabashada (MTTR)","text":"Celcelis ahaan, inta ay qaadato in adeeg mar kale shaqeeyo kadib marka uu jabo. MTTR waxay macnayn kartaa waxyaabo wax yar kala duwan, ee sheeg waxa aad cabbirayso.","also":["MTTR","mean time to recover","mean time to restore"]},{"id":"mtbf","g":"run","word":"Celceliska waqtiga u dhexeeya fashilaadyada (MTBF)","text":"Celcelis ahaan, inta uu adeeg shaqeeyo ka hor inta aan wax jabin.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Database-ka maaraynta habaynta (CMDB)","text":"Liiska dhammaan alaabta habaynta iyo sida ay isku xiran yihiin, si aad u aragto waxa ku tiirsan waxa kale.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Hanti (Asset)","text":"Wax kasta oo qiimo leh oo aad leedahay ama aad lacag ku bixiso si adeegga loo socodsiiyo, sida laptop, shati software ama domain.","also":["asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Qorshaynta awoodda (Capacity planning)","text":"Hubinta in ay jiri doonto awood kombuyuutar, kayd iyo dad ku filan waxa soo socda.","also":["capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Balaadhin (Scaling)","text":"La qabsiga isticmaalayaal badan iyadoo mashiin la siinayo awood dheeraad ah (scaling up) ama lagu darayo mashiinno badan (scaling out).","also":["scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Joogtaynta ganacsiga (Business continuity)","text":"Qorshayaal lagu sii wado waxyaabaha muhiimka ah marka wax weyn khaldamaan, sida lumitaanka xafiis, alaab-qeybiye muhiim ah ama kombuyuutarada.","also":["business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Soo kabashada musiibada (DR)","text":"Qorshaha iyo qalabka lagu soo celiyo adeeg kadib dhibaato culus, sida lumitaanka xarun xog oo dhan.","also":["DR","disaster recovery"]},{"id":"rto","g":"run","word":"Hadafka waqtiga soo kabashada (RTO)","text":"Waqtiga ugu dheer ee adeeggu istaagi karo kadib musiibo ka hor inta aan laga rabin inuu mar kale shaqeeyo.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Hadafka barta soo kabashada (RPO)","text":"Inta xog dhawaan ah ee aad u adkaysan karto inaad lumiso, oo waqti lagu cabbiro. RPO hal saac ah waxay ka dhigan tahay kayd (backup) ugu yaraan saacad kasta.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Keyd dheeraad ah (Redundancy)","text":"Haysashada kuwo kale oo diyaar ah, sida server labaad, si hal cillad aysan adeegga u joojin.","also":["redundancy"]},{"id":"failover","g":"run","word":"Wareejin otomaatig ah (Failover)","text":"Si iskiis ah ugu wareegidda nidaam kayd ah marka kii caadiga ahaa fashilmo.","also":["failover","fail over"]},{"id":"spof","g":"run","word":"Hal meel oo fashil (Single point of failure)","text":"Hal qayb oo marka ay jabto wax walba la dhacda, sababtoo ah ma jiro mid kayd ah.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Daaqadda dayactirka (Maintenance window)","text":"Waqti la qorsheeyay oo adeeg la hakin karo ama uu gaabis noqon karo dayactir awgeed, oo isticmaalayaasha hore loogu sheego.","also":["maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Wareejin (Handover)","text":"U gudbinta shaqada, aqoonta iyo masuuliyadda qof kale ama koox kale, si aan waxba u lumin.","also":["handover","handovers"]},{"id":"kb","g":"run","word":"Kaydka aqoonta (Knowledge base)","text":"Ururin maqaallo caawimo iyo jawaabo ah, oo loogu talagalay isticmaalayaasha iyo kooxda.","also":["knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Raalli-ahaanshaha macmiilka (CSAT)","text":"Dhibco ka yimaada isticmaalayaasha oo sheegaya inta ay ku faraxsan yihiin, badanaa la weydiiyo kadib marka codsi la xiro.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Alaab-qeybiye (Supplier)","text":"Shirkad dibadda ah oo aad ku tiirsan tahay, sida bixiyaha hosting-kaaga. Waxaa kaloo loo yaqaan vendor ama third party.","also":["supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Joojinta adeegga (Service retirement)","text":"Demidda adeeg si joogto ah oo ammaan ah: u sheegidda isticmaalayaashiisa, maaraynta xogtiisa iyo galitaankiisa, iyo joojinta kharashkiisa.","also":["service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Dhammaadka nolosha (End of life, EOL)","text":"Marka soo saaraha alaab uu joojiyo cusboonaysiinta iyo taageerada, sidaas darteed waa in la beddelo.","also":["EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Amniga internetka (Cybersecurity)","text":"Ka ilaalinta nidaamyada iyo xogta in la jebsado, la xado ama la waxyeeleeyo.","also":["cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Xaqiijinta aqoonsiga (Authentication)","text":"Hubinta cidda qof yahay, badanaa eray sir ah ama koodh. Badanaa waxaa loo soo gaabiyaa authn.","also":["authentication","authn"]},{"id":"authz","g":"sec","word":"Ruqsaynta (Authorisation)","text":"Hubinta waxa qofka loo oggol yahay inuu sameeyo marka aad ogaato cidda uu yahay. Badanaa waxaa loo soo gaabiyaa authz.","also":["authorisation","authz","authorization"]},{"id":"mfa","g":"sec","word":"Xaqiijin dhowr-tallaabo ah (Multi-factor authentication, MFA)","text":"Gelitaanka adigoo isticmaalaya laba caddayn ama ka badan, sida eray sir ah iyo koodh taleefankaaga ku yimaada. Waxaa kaloo loo yaqaan two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","multi-factor authentication"]},{"id":"sso","g":"sec","word":"Gelid hal mar (Single sign-on, SSO)","text":"Hal mar gelid si aad u gasho nidaamyo badan, sida inaad meel walba ku isticmaasho akoonkaaga shaqada.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Maamulaha erayada sirta (Password manager)","text":"App sameeya erayo sir ah oo adag oo kuu xasuusta.","also":["password manager","password managers"]},{"id":"secret","g":"sec","word":"Sir (Secret)","text":"Eray sir ah, fure ama koodh gaar ah oo barnaamij u isticmaalo inuu wax galo. Waa in aan marna la wadaagin ama koodhka lagu qorin.","also":["secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Furaha API (API key)","text":"Koodh sir ah oo u oggolaanaya barnaamij inuu isticmaalo API-ga adeeg kale, oo muujiya cidda isticmaalaysa (oo lacagta ka bixisa).","also":["API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Access token (ogolaansho ku meel gaar ah)","text":"Ogolaansho ku meel gaar ah oo caddeeya in barnaamij loo oggol yahay inuu galo, sidaas darteed uusan u baahnayn erayga sirta ah mar kasta. Ka duwan token-ka AI.","also":["access token","access tokens"]},{"id":"encryption","g":"sec","word":"Sir-qarin (Encryption)","text":"Isku qasidda macluumaadka si uu u akhrin karo oo keliya qofka haysta furaha saxda ah.","also":["encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Habka ammaanka ah ee bogagga web-ku ku safraan, oo ay muujiso qufulka browser-kaaga, si qof dhexda ku jiraa uusan u akhrin karin ama u beddeli karin."},{"id":"cert","g":"sec","word":"Shahaadada SSL/TLS","text":"Kaar aqoonsi dijitaal ah oo website u oggolaanaya inuu caddeeyo cidda uu yahay oo uu isticmaalo HTTPS. Waqtigiisu wuu dhacaa, sidaas darteed waa in la cusboonaysiiyo.","also":["SSL/TLS certificate","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Oggolaanshaha (Permissions)","text":"Xeerarka go'aamiya cidda wax arki karta ama beddeli karta.","also":["permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Xuquuqda ugu yar (Least privilege)","text":"Siinta qof kasta ama barnaamij kasta galitaanka uu runtii u baahan yahay oo keliya, iyo muddada uu u baahan yahay oo keliya.","also":["least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Xakamaynta galitaanka iyadoo loo eegayo doorka (RBAC)","text":"Siinta galitaanka iyadoo loo eegayo doorka, sida daawade ama tafatire, halkii qof-qof loo siin lahaa.","also":["RBAC","role-based access","role-based access control"]},{"id":"vuln","g":"sec","word":"Daciifnimo (Vulnerability)","text":"Daciifnimo qof isticmaali karo si uu u soo jebiyo ama waxyeello u geysto.","also":["vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Daciifnimo ay weerarayaashu yaqaanaan ka hor inta soo saareyaashu aysan helin wakhti ay ku hagaajiyaan.","also":["zero-day","zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware (Software waxyeello leh)","text":"Software waxyeello leh, sida fayrasyada, oo loo sameeyay in lagu burburiyo, lagu basaaso ama lagu xado.","also":["malware"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware xira faylashaada oo lacag ku dalba si loo furo. Kayd (backup) wanaagsan ayaa ah difaaca ugu fiican.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing (Khiyaano farriin)","text":"Fariimo been ah oo isku daya inay kugu khiyaameeyaan inaad bixiso erayo sir ah ama lacag, ama aad furto wax waxyeello leh.","also":["phishing","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Khiyaanada dadka (Social engineering)","text":"Khiyaamaynta dadka, halkii kombuyuutarada, si ay galitaan u bixiyaan, sida wicitaan been ah oo sheeganaya “taageerada IT”."},{"id":"firewall","g":"sec","word":"Firewall (Darbi dab)","text":"Ilaaliye go'aamiya taraafikada shabakadda ee soo geli karta ama bixi karta.","also":["firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Gaabinta virtual private network: xiriir gaar ah oo la isku qasay oo internetka dushiisa mara, badanaa loo isticmaalo in si ammaan ah loo gaaro nidaamyada shaqada.","also":["virtual private network","VPN"]},{"id":"ddos","g":"sec","word":"Diidmada adeegga (DoS, DDoS)","text":"Ku buuxinta adeeg taraafik been ah oo aad u badan ilaa dadka dhabta ahi aysan isticmaali karin. DDoS waxay ka dhigan tahay inay ka timaado kombuyuutaro badan isla mar.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Tijaabada duulaanka (Penetration test, pen test)","text":"Shaqaalaysiinta khubaro saaxiibo ah oo isku daya inay soo jebiyaan, si daciifnimooyinka loo helo ka hor inta aysan weerarayaal dhab ahi helin.","also":["pen test","pen testing","penetration testing","pentest","penetration test"]},{"id":"audit","g":"sec","word":"Baaritaanka amniga (Security audit)","text":"Hubin taxadar leh oo lagu eego inta wax si fiican loo ilaaliyo, iyadoo la barbar dhigayo liis hababka wanaagsan.","also":["security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Qaabaynta khatarta (Threat modelling)","text":"Ka fikirka cidda weerari karta wax, sida ay u samayn karto, iyo waxa aad samayn lahayd si aad u joojiso.","also":["threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Jebinta xogta (Data breach)","text":"Marka macluumaad gaar ah ay gaaraan dad aan xaq u lahayn, ama la lumiyo ama la beddelo oggolaansho la'aan.","also":["data breach","data breaches"]},{"id":"pii","g":"sec","word":"Xogta shakhsi ahaaneed (Personal data)","text":"Macluumaad kasta oo ku saabsan qof la aqoonsan karo, sida magac, ciwaanka iimaylka ama goobta. Waxaa kaloo loo yaqaan PII.","also":["personal data","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Sharciga Yurub ee xogta shakhsi ahaaneed (UK-gu wuxuu leeyahay nooc u gaar ah): ururi oo keliya waxa aad u baahan tahay, ammaan ku hay, una oggolow dadka inay arkaan ama tirtiraan xogtooda.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Ilaalinta xogta (Data protection)","text":"Daryeelka xogta shakhsi ahaaneed si sax ah oo sharciga waafaqsan.","also":["data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Siyaasadda asturnaanta (Privacy policy)","text":"Bog dadweyne oo sheegaya xogta shakhsi ahaaneed ee aad ururiso, sababta, iyo waxa aad ku samayso.","also":["privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Raalli ahaansho (Consent)","text":"Haa cad oo xor ah oo qof ka bixiyo in xogtiisa loo isticmaalo hab gaar ah. Mar kasta wuu ka noqon karaa.","also":["consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Fayl yar oo website ku keydiyo browser-kaaga si uu wax u xasuusto, sida inaad gashay akoonkaaga. Qaarkood waxay u baahan yihiin oggolaanshahaaga marka hore.","also":["cookie","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Yaraynta xogta (Data minimisation)","text":"Ururinta iyo haynta xogta shakhsi ahaaneed ee aad runtii u baahan tahay shaqada oo keliya.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Haynta xogta (Data retention)","text":"Inta xogta la hayo ka hor inta aan la tirtirin. In aan la hayn wax ka badan inta loo baahan yahay ayaa ammaan badan, badanaana waa sharci.","also":["data retention","retention period"]},{"id":"anon","g":"sec","word":"Magac-ka-saarid (Anonymisation)","text":"Beddelidda xogta si aan qofna si macquul ah looga aqoonsan karin mar dambe.","also":["anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Magac-beddelid (Pseudonymisation)","text":"Ku beddelidda magacyada iyo faahfaahinta kale koodhad, iyadoo fure gooni loo hayo si dib loogu xiro. Weli waa xog shakhsi ahaaneed.","also":["pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Heshiiska habaynta xogta (DPA)","text":"Qandaraas sheegaya sida alaab-qeybiye u maarayn karo xogta shakhsi ahaaneed isagoo ku matalaya.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Qiimeynta saameynta ilaalinta xogta (DPIA)","text":"Eegis taxadar leh, ka hor intaan la bilaabin, oo ku saabsan sida qorshe isticmaalaya xogta shakhsi ahaaneed uu dadka u saameyn karo iyo sida loo yareeyo khatarta.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Diiwaanka baaritaanka (Audit log)","text":"Diiwaan muujinaya cidda waxa samaysay iyo goorta, si falalka mar dambe loo hubin karo.","also":["audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"U hoggaansamid (Compliance)","text":"Raacidda sharciyada, xeerarka iyo heerarka ku khuseeya, iyo awoodda inaad muujiso inaad raacdo.","also":["compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Heer caalami ah oo caan ah oo lagu maamulo amniga macluumaadka. Shirkaduhu waxay heli karaan shahaado ku salaysan.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Warbixin Mareykan ah, oo ay hubiyeen hanti-dhowrayaal dibadda ah, oo muujinaysa in shirkad si fiican u daryeesho xogta macaamiisha.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI hawl keligiis ka shaqeeya: wuxuu akhriyaa koodhka, sameeyaa isbeddello, socodsiiyaa hubinno, kadibna warbixin soo celiyaa. Shaqadiisa weli waa la hubiyaa.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Qaybo yaryar oo qoraal ah oo AI akhriyo oo qoro, mid kastaa qiyaastii saddex meelood oo afar meelood oo eray ah. Isticmaalka AI waxaa lagu tiriyaa tokens, sidaas darteed tokens yar ayaa qorshahaaga ka reeba wax badan.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Amar yar oo iskiis u socda waqti go'an, tusaale ahaan marka kalfadhi AI bilaabmo, si kooxdu u maqasho faalladaada.","also":["hooks"]},{"id":"ai","g":"ai","word":"Sirdoonka macmalka ah (Artificial intelligence, AI)","text":"Nidaamyo kombuyuutar oo qabta waxyaabo aan inta badan u malayno inay qof u baahan yihiin, sida qorista, ka jawaabidda su'aalaha ama aqoonsiga sawirrada.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Barashada mashiinka (Machine learning, ML)","text":"Hab kombuyuutarada lagu baro inay qaabab ka bartaan tusaalayaal badan, halkii xeerar sax ah la siin lahaa.","also":["ML","machine learning"]},{"id":"model","g":"ai","word":"Model","text":"“Maskaxda” la tababaray ee nidaam AI ah, oo la dhisay iyadoo wax laga bartay tusaalayaal aad u tiro badan. Models-ku way kala duwan yihiin xirfad, xawaare iyo qiimo.","also":["models","AI model","model AI"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"Model AI ah oo lagu tababaray qoraal aad u badan, si uu u akhriyi karo oo u qori karo luuqad.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"AI abuure (Generative AI)","text":"AI abuura waxyaabo cusub, sida qoraal, sawirro ama koodh, halkii uu kaliya kala saari lahaa ama ogaan lahaa.","also":["GenAI","Generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Barnaamij aad la hadasho luuqadda maalinlaha ah, adigoo qorayo ama hadlaya.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt (Tilmaan)","text":"Waxa aad siiso AI: su'aashaada ama tilmaamahaaga, iyo wax kasta oo aad u dhiibto. Prompt-yada cad badanaa waxay keenaan jawaabo ka wanaagsan.","also":["prompt","prompts"]},{"id":"prompteng","g":"ai","word":"Qorista prompts (Prompt engineering)","text":"Xirfadda qorista prompt-yo keena natiijooyin la isku halayn karo oo waxtar leh.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Tilmaanta nidaamka (System prompt)","text":"Tilmaamo asaasi ah oo AI-gu helo ka hor inta aan wada-hadalku bilaaban, kuwaas oo dejiya doorkiisa iyo xeerarkiisa. Waxay ka miisaan culus yihiin waxa aad qorto.","also":["system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Macnaha guud (Context)","text":"Wax kasta oo AI arki karo markuu shaqeynayo: tilmaamaha, fariimahaaga, faylasha uu akhriyay iyo jawaabihii hore.","noTip":1},{"id":"ctxwin","g":"ai","word":"Daaqadda macnaha (Context window)","text":"Inta uu AI maskaxda ku hayn karo hal mar, oo lagu cabbiro tokens. Intaas markay dhaafto, qaybaha hore waa la tuuraa ama waa la soo koobaa.","also":["context window","context windows"]},{"id":"session","g":"ai","word":"Kalfadhi (Session)","text":"Hal wada-hadal shaqo oo AI lala yeesho, laga bilaabo bilowga ilaa dhammaadka. Kalfadhi cusub wuxuu ku bilaabmaa xusuus cusub.","also":["session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Xusuus (Memory)","text":"Qoraallo AI-gu hayo inta u dhaxaysa kalfadhiyada, si uu u xasuusto waxyaabaha aad door bidayso iyo go'aannadii hore.","noTip":1},{"id":"hallucination","g":"ai","word":"Male been ah (Hallucination)","text":"Marka AI uu si kalsooni leh u sheego wax la hal-abuuray ama khaldan. Hubi xaqiiqooyinka muhiimka ah.","also":["hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Tababar (Training)","text":"Barista model iyadoo la tusinayo tusaalayaal aad u tiro badan, ka hor inta aan cidi isticmaalin.","also":["training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Xogta tababarka (Training data)","text":"Tusaalayaasha uu model ka bartay. Aqoontiisu waxay ku egtahay taariikhda xogtaas la ururiyay.","also":["training data","training set"]},{"id":"cutoff","g":"ai","word":"Taariikhda gooynta aqoonta (Knowledge cutoff)","text":"Taariikhda ay ku dhammaato aqoonta ku dhex jirta AI. Ma ogaan doono waxyaabaha ka dambeeya haddii uusan raadin.","also":["knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Hagaajin gaar ah (Fine-tuning)","text":"Tababar dheeraad ah oo model jira loogu sameeyo tusaalayaashaada, si uu uga fiicnaado hal shaqo gaar ah.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Isticmaalka model-ka (Inference)","text":"Model AI oo dhab ahaan loo isticmaalayo si uu wax uga jawaabo, ee aan ahayn in la tababarayo.","also":["inference","model inference"]},{"id":"tooluse","g":"ai","word":"Isticmaalka qalabka (Tool use)","text":"AI oo awood u leh inuu wax qabto, ee aan ahayn hadal keliya: inuu socodsiiyo amarro, akhriyo faylal ama ka raadiyo webka, iyadoo loo marayo qalabka uu app-ku siiyo.","also":["tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Wakiil hoose (Subagent)","text":"AI caawiye ah oo AI-ga ugu weyn u dhiibo shaqo ka yar, kadibna natiijada ka helo.","also":["subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Wakiillo badan (Multi-agent)","text":"AI dhawr ah oo hal shaqo wada qabta, mid kastaa qayb u gaar ah leh, sida koox yar.","also":["multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Madaxbannaani (Autonomy)","text":"Inta uu AI keligiis samayn karo ka hor inta aysan waajib ku noqon inuu qof weydiiyo.","also":["autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Qof ku jira wareegga (Human in the loop)","text":"Ku haynta qof ku lug leh si uu u hubiyo ama u oggolaado waxa AI sameeyo meelaha muhiimka ah. AI-gile dhexdiisa, adiga ayaa ah.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Xayndaabyada badbaadada (Guardrails)","text":"Xadad iyo hubinno ammaan ka dhiga falalka AI, sida in oggolaansho loo baahdo ka hor inta aan wax la daah-furin. Waxay yareeyaan khatarta khaladaadka, laakiin gebi ahaanba ma baabi'iyaan.","also":["guardrail","guardrails"]},{"id":"rag","g":"ai","word":"RAG (marka hore raadi ka dibna jawaab)","text":"U oggolaanshaha AI inuu wax ka raadiyo dukumeentiyadaada ka hor inta uusan jawaabin, si jawaabihiisu ugu salaysnaadaan xaqiiqooyinkaaga.","also":["RAG","retrieval augmented generation","retrieval-augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"U beddelidda qoraal liis tirooyin ah oo qabta macnihiisa, si kombuyuutar u helo waxyaabo macno isku dhow leh.","also":["embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Database-ka vector (Vector database)","text":"Database loo dhisay inuu raadiyo liisaskaas tirooyinka ah (embeddings), si loo helo agab macno la mid ah leh.","also":["vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Hab la wadaago oo qalab iyo ilo xog loogu xiro app-yada AI, si AI-gu u isticmaali karo.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Heerkulka (Temperature)","text":"Dejin go'aamisa inta ay jawaabaha AI-gu dhiirran yihiin. Mid hoose wuxuu bixiyaa jawaabo deggan oo la saadaalin karo; mid sare wuxuu bixiyaa kuwo kala duwan. Midkoodna kama dhigo inuu mar walba sax yahay.","also":["temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Awood u leh inuu la shaqeeyo in ka badan hal nooc oo macluumaad, sida qoraal, sawirro iyo cod.","also":["multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Qiimeyn (Evaluation, eval)","text":"Tijaabo la qorsheeyay oo lagu eego inta uu AI si fiican ugu shaqeeyo tusaalayaal la doortay, si aad u barbar dhigto models ama prompts.","also":["evaluation","eval","evals"]},{"id":"bias","g":"ai","word":"Eex (Bias)","text":"Marka AI (ama qof) si aan caddaalad ahayn ugu janjeero hal dhinac, badanaa waxa uu ka bartay dartiis.","also":["bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"AI mas'uul ah (Responsible AI)","text":"Isticmaalka AI si caddaalad ah, ammaan ah oo daacad ah, iyadoo dadku weli ka jawaabayaan natiijooyinka.","also":["responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Khiyaano ay tilmaamo qarsoon oo ku jira bog web ama fayl isku dayaan inay AI ku qasbaan inuu sameeyo wax isticmaalihiisu aanu codsan.","also":["prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Xadka xawaaraha (Rate limit)","text":"Xad ku saabsan inta codsi ee aad u diri karto adeeg muddo go'an gudaheed. Haddii aad dhaafto, waa inaad sugtaa.","also":["rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Xadka isticmaalka (Usage limit)","text":"Inta shaqo AI ah ee qorshahaagu oggol yahay muddo gudaheed, kaddibna wuu hakadaa ama kharash dheeraad ah ayuu keenaa.","also":["usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Dhisidda software inta badan adigoo AI u sharaxaya waxa aad rabto oo uu koodhka qoro.","also":["vibe coding","vibe-coding"]},{"id":"budget","g":"money","word":"Miisaaniyad (Budget)","text":"Qaddarka lacagta ah ee wax loo qoondeeyay.","also":["budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Qiyaasta kharashka (Cost estimate)","text":"Qiyaas ugu fiican oo ku saabsan inta uu wax ku kacayo ka hor intaadan bilaabin.","also":["cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Soo celinta maalgashiga (ROI)","text":"Waxa aad dib u hesho marka lala barbar dhigo waxa aad gelisay. Haddii ay togan tahay, wuu mudnaa.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Wadarta kharashka lahaanshaha (TCO)","text":"Waxa uu wax runtii ku kacayo inta uu nool yahay oo dhan, ee aan ahayn qiimaha iibsiga oo keliya: socodsiinta, taageerada, cusboonaysiinta iyo ugu dambayntii hawlgab ka dhigista.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx iyo OpEx","text":"CapEx waa lacag horay loogu bixiyo waxyaabo aad haysanayso; OpEx waa kharash joogto ah, sida biilasha bishii.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Rukumo (Subscription)","text":"Lacag bixin joogto ah, badanaa bil kasta ama sannad kasta, si aad u sii wadatid isticmaalka wax.","also":["subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software adeeg ahaan (SaaS)","text":"Software aad isticmaasho khadka oo aad ku bixiso rukumo, halka soo saaruhu kuu socodsiiyo.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Bixi sida aad isticmaasho (Pay as you go)","text":"Bixinta waxa aad isticmaasho oo keliya, sida cloud computing ama AI tokens.","also":["pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Dheeraad (Overage)","text":"Isticmaal ka badan inta qorshahaagu ku jirto, oo kharash dheeraad ah keeni kara.","also":["overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Digniinta biilasha (Billing alert)","text":"Fariin marka kharashka ama isticmaalku gaaro heer aad dooratay. Waxay ku digtaa, laakiin had iyo jeer ma joojiso kharashyo dheeraad ah.","also":["billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Heerka bilaashka ah (Free tier)","text":"Heer bilaash ah oo ka mid ah adeeg lacag leh, oo xadad leh. Wuu ku habboon yahay marka la bilaabayo.","also":["free tier","free plan"]},{"id":"pricing","g":"money","word":"Qorshaha qiimaha (Pricing plan)","text":"Xirmooyinka kala duwan ee adeeg iibiyo, mid kastaa leh qiimihiisa iyo xadkiisa.","also":["pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Shati (Licence)","text":"Xeerarka ku saabsan sida aad u isticmaali karto, u koobiyeyn karto, u beddeli karto ama u wadaagi karto wax uu qof kale sameeyay, sida software, far-qoraal ama sawirro.","also":["licence","licences","license","licenses","shati","shatiyo"],"noTip":1},{"id":"opensource","g":"money","word":"Open source (koodh furan)","text":"Software koodhkiisa qof kasta akhrin karo, isticmaali karo oo badanaa bilaash ku beddeli karo, iyadoo la raacayo xeerarka shatigiisa.","also":["open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Shatiga open source (Open source licence)","text":"Xeerarka la socda koodhka open source. Qaarkood waxay kuu oggolaadaan ku dhawaad wax kasta (sida MIT); qaar kale waxay ku weydiistaan inaad sidoo kale wadaagto isbeddelladaada (sida GPL).","also":["open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary (gaar loo leeyahay)","text":"Ay leedahay shirkad, lagumana koobiyayn karo ama beddeli karo si xor ah. Waa lidka open source.","also":["proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Xuquuqda daabacaadda (Copyright)","text":"Xaqa sharci ee abuuraha u leeyahay inuu xakameeyo nuqullada shaqadiisa, oo ay ku jiraan koodh iyo qoraal.","also":["copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Hanti maskaxeed (Intellectual property, IP)","text":"Fikrado iyo abuurro uu sharcigu u arko kuwo la leeyahay, sida koodh, naqshado, magacyo iyo summado (logos).","also":["IP","intellectual property"]},{"id":"tos","g":"money","word":"Shuruudaha adeegga (Terms of service)","text":"Xeerarka aad ku raacdo marka aad adeeg isticmaasho.","also":["terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Qandaraas (Contract)","text":"Heshiis qoran oo u dhexeeya laba dhinac oo sharcigu taageerayo.","also":["contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Bayaanka shaqada (SOW)","text":"Dukumeenti si sax ah u qeexaya shaqada la qabanayo, goorta la dhammaynayo iyo qiimaha.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Qiimo go'an (Fixed price)","text":"Qiimo la isku raacay oo shaqada oo dhan ah, si kasta oo ay u dheeraato.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Waqti iyo alaab (Time and materials)","text":"Bixinta saacadaha runtii la shaqeeyay iyo waxyaabaha runtii la isticmaalay, halkii qiimo go'an la bixin lahaa.","also":["time and materials","T&M"]},{"id":"invoice","g":"money","word":"Biil (Invoice)","text":"Biil lagu codsanayo lacagta shaqo la qabtay ama alaab la keenay.","also":["invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Ku xidhnaanta alaab-qeybiyaha (Vendor lock-in)","text":"Marka ka guurista alaab-qeybiye ay aad u adag tahay ama qaali tahay ilaa aad ku xayirto.","also":["vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"Iibsashada (Procurement)","text":"Habka doorashada iyo ka iibsashada alaab-qeybiyayaasha.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Magdhowga adeegga (Service credit)","text":"Lacag celin ama qiimo dhimis aad hesho marka alaab-qeybiyuhu uusan gaarin SLA-ga.","also":["service credit","service credits"]}]}};
